// questions-attacking-concepts.js
// Cyber Defense Runner - Attacking Concepts question bank (100 questions).
// Educational/defensive framing only (recognize and understand attacker techniques).
// Standalone data file. NOT yet merged into questions.js.
// Distribution: tiers 50 Beginner / 35 Intermediate / 15 Advanced.
//               correct index balanced 25 / 25 / 25 / 25 across A/B/C/D.

const ATTACKING_CONCEPTS_QUESTIONS = [
  { id:"attacking-concepts-001", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is 'reconnaissance' in an attack?", options:["Gathering information about a target before attacking","Encrypting all of the target's important files for ransom","Installing security updates on the target's servers","Permanently deleting the target's stored data"], correct:0, explain:"Recon is the information-gathering stage where attackers learn about a target's systems, people, and weaknesses.", reward:"Recon Awareness" },
  { id:"attacking-concepts-002", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is phishing?", options:["Connecting office computers using a special network cable","Tricking people into revealing information or clicking malicious links","Backing up company files on a fixed daily schedule","A firewall rule that blocks unwanted incoming traffic"], correct:1, explain:"Phishing uses deceptive messages to trick people into giving up credentials or running malicious content.", reward:"Phishing Sense" },
  { id:"attacking-concepts-003", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a brute-force attack?", options:["Safely backing up important files to another disk","A built-in feature found on most modern firewalls","One common type of network cable","Trying many passwords or keys until one works"], correct:3, explain:"Brute force systematically tries many combinations until the correct password or key is found.", reward:"Credential Guard" },
  { id:"attacking-concepts-004", tier:"Beginner", topic:"Attacking Concepts", prompt:"In attacks, what does 'exploitation' mean?", options:["Copying important files to a backup location","Encrypting the contents of an entire disk","Taking advantage of a vulnerability to gain access or run code","Resetting a forgotten account password"], correct:2, explain:"Exploitation is using a weakness to make a system do something it shouldn't, such as run attacker code.", reward:"Exploit Awareness" },
  { id:"attacking-concepts-005", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is privilege escalation?", options:["Copying important files to a backup location","Gaining higher access rights than originally allowed","Encrypting the contents of an entire disk","Sending routine email to other users"], correct:1, explain:"Privilege escalation is when an attacker raises their access, for example from a normal user to admin.", reward:"Access Guard" },
  { id:"attacking-concepts-006", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is 'credential access' in an attack?", options:["Stealing usernames, passwords, or keys","Backing up files","Speeding up the network","Patching software"], correct:0, explain:"Credential access is the stage where attackers steal logins or keys to expand their reach.", reward:"Credential Guard" },
  { id:"attacking-concepts-007", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is 'lateral movement'?", options:["Backing up important data to another location","Applying security patches to network servers","Moving from one compromised system to others inside the network","Encrypting the contents of an entire disk"], correct:2, explain:"Lateral movement is how attackers spread from an initial foothold to additional internal systems.", reward:"Segmentation Sense" },
  { id:"attacking-concepts-008", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is 'persistence' in an attack?", options:["Copying important data to a backup location","Configuring a standard rule on the firewall","Choosing a password to protect an account","Keeping access so the attacker remains even after reboots or logouts"], correct:3, explain:"Persistence lets attackers maintain their foothold over time, surviving restarts and clean-ups.", reward:"Persistence Watch" },
  { id:"attacking-concepts-009", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is 'command and control' (C2) in an attack?", options:["The channel an attacker uses to remotely control compromised systems","A spare server used to store file backups","Configuring a standard rule on the firewall","Storing user passwords inside a secure vault"], correct:0, explain:"C2 is how attackers send commands to and receive data from machines they have compromised.", reward:"Traffic Watch" },
  { id:"attacking-concepts-010", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is data 'exfiltration'?", options:["Safely backing up data to another location","Stealing data and moving it out of the organization","Encrypting a backup copy of important files","Applying a security patch to a server"], correct:1, explain:"Exfiltration is when attackers copy and remove data from the victim's environment.", reward:"Data Watch" },
  { id:"attacking-concepts-011", tier:"Beginner", topic:"Attacking Concepts", prompt:"In attack terms, what does 'impact' mean?", options:["Creating a safe backup copy of important data","Scanning the network to find open ports","Logging in normally with a valid user account","The damage done, such as destroying, encrypting, or disrupting systems"], correct:3, explain:"Impact is the harmful effect of an attack, like ransomware encryption, data destruction, or downtime.", reward:"Impact Sense" },
  { id:"attacking-concepts-012", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is social engineering?", options:["A standard network communication protocol","Backing up files on a fixed schedule","Manipulating people into taking unsafe actions or revealing information","Changing a configuration setting on the firewall"], correct:2, explain:"Social engineering targets human trust and behavior rather than exploiting software directly.", reward:"Human Firewall" },
  { id:"attacking-concepts-013", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is the main idea behind a web injection attack like SQL injection?", options:["Creating a backup copy of a database","Tricking an app into running attacker-supplied input as a command","Encrypting a single web page on a site","Improving how quickly a website loads"], correct:1, explain:"Injection attacks slip malicious input into a query or command the app then runs.", reward:"Web Defense" },
  { id:"attacking-concepts-014", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a 'password spraying' attack?", options:["Trying one common password across many accounts","A safe method for backing up data","A built-in firewall rule","Encrypting stored passwords at rest"], correct:0, explain:"Password spraying tries a few common passwords against many accounts to avoid lockouts on any one.", reward:"Credential Guard" },
  { id:"attacking-concepts-015", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is an 'attack chain' (or kill chain)?", options:["A weekly schedule for running backups","Rules a firewall applies to traffic","The sequence of steps an attacker follows from start to goal","Policy covering required password length"], correct:2, explain:"An attack chain describes the ordered stages, like recon, access, escalation, and impact, of an attack.", reward:"Chain Awareness" },
  { id:"attacking-concepts-016", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is 'passive reconnaissance'?", options:["Loudly scanning every port on the target's network","Calling the help desk to reset a password","Installing malicious software on the target","Collecting public information without directly touching the target's systems"], correct:3, explain:"Passive recon uses public sources without interacting with the target's systems, so it is hard to detect.", reward:"Recon Awareness" },
  { id:"attacking-concepts-017", tier:"Intermediate", topic:"Attacking Concepts", prompt:"A 'spear phishing' email differs from regular phishing because it is...?", options:["Targeted at a specific person using personal details","Sent at random to a huge list of people","Always completely harmless to recipients","A routine software patch for an email app"], correct:0, explain:"Spear phishing is tailored to a specific person or role using researched details, making it more convincing.", reward:"Phishing Sense" },
  { id:"attacking-concepts-018", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why does a long, complex password resist brute force better?", options:["Longer passwords simply look more professional","There are far more combinations to try","Such passwords are typed in much faster","They use less memory when stored on disk"], correct:1, explain:"More length and character variety means vastly more possibilities, making guessing impractical.", reward:"Credential Guard" },
  { id:"attacking-concepts-019", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is an 'exploit'?", options:["A safety copy of important files","Hardware that filters network traffic","A secret phrase used to log into accounts","Code or a technique that abuses a specific vulnerability"], correct:3, explain:"An exploit is the method or code that takes advantage of a particular vulnerability.", reward:"Exploit Awareness" },
  { id:"attacking-concepts-020", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is the difference between vertical and horizontal privilege escalation?", options:["They are really just two names for the same idea","Vertical escalation simply adds more disk space","Vertical gains higher rights, while horizontal takes another user's same-level access","Horizontal escalation only encrypts the stored data"], correct:2, explain:"Vertical escalation moves up to higher privileges; horizontal moves sideways to another account's access.", reward:"Access Guard" },
  { id:"attacking-concepts-021", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are reused passwords dangerous if one site is breached?", options:["Reused passwords tend to load more slowly","Attackers try the stolen password on your other accounts","Such passwords use more memory to store","Shared passwords simply look unprofessional"], correct:1, explain:"If you reuse a password, a breach at one site lets attackers log into your other accounts.", reward:"Credential Guard" },
  { id:"attacking-concepts-022", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why does network segmentation hinder lateral movement?", options:["It limits which systems a compromised host can reach","It noticeably speeds up the office Wi-Fi","It automatically encrypts all outgoing email","It deletes old log files to save space"], correct:0, explain:"Segmentation restricts connections between zones, making it harder to hop from one system to others.", reward:"Segmentation Sense" },
  { id:"attacking-concepts-023", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Which is an example of a persistence technique?", options:["Restoring files from a recent backup","Applying the latest patch to a server","Adding a malicious task that runs automatically at startup","Rotating an encryption key on schedule"], correct:2, explain:"Auto-start entries like scheduled tasks or startup items re-launch attacker code after reboots.", reward:"Persistence Watch" },
  { id:"attacking-concepts-024", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers often disguise C2 traffic as normal web traffic?", options:["To deliberately use up more electrical power","To make the traffic look more colorful","To make the connection run noticeably faster","To blend in and avoid being noticed or blocked"], correct:3, explain:"Hiding C2 inside ordinary-looking traffic, such as HTTPS, helps it evade detection.", reward:"Traffic Watch" },
  { id:"attacking-concepts-025", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why might a large, unusual outbound data transfer be worth investigating?", options:["It can indicate data being exfiltrated","It always means faster internet","It is a backup by default","It is harmless noise"], correct:0, explain:"Big or odd outbound transfers can be a sign of stolen data leaving the network.", reward:"Data Watch" },
  { id:"attacking-concepts-026", tier:"Beginner", topic:"Attacking Concepts", prompt:"Ransomware is an example of which attack goal?", options:["Reconnaissance, the early information-gathering stage","Impact, by denying access to data until a ransom is paid","Creating a routine backup of important files","Applying a security patch to fix a flaw"], correct:1, explain:"Ransomware's impact is denying access through encryption to pressure victims into paying.", reward:"Impact Sense" },
  { id:"attacking-concepts-027", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is a social engineering tactic?", options:["Applying a patch to an internal server","Encrypting the data on a full disk","Rotating an old encryption key","Pretending to be IT support to get a password"], correct:3, explain:"Impersonating a trusted role like IT to extract information is classic social engineering.", reward:"Human Firewall" },
  { id:"attacking-concepts-028", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why does validating and sanitizing user input help prevent web attacks?", options:["It noticeably speeds up the whole site","It changes the colors shown on the page","It stops malicious input from being treated as code or commands","It automatically backs up the site's data"], correct:2, explain:"Checking and cleaning input prevents attackers from injecting commands through form fields or URLs.", reward:"Web Defense" },
  { id:"attacking-concepts-029", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why can password spraying avoid triggering account lockouts?", options:["It encrypts each password before sending it","It tries only a few passwords per account, staying under lockout limits","It completes much faster than other methods","It uses far less power on the attacker's side"], correct:1, explain:"By guessing only a little on each account, spraying stays below per-account lockout thresholds.", reward:"Credential Guard" },
  { id:"attacking-concepts-030", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is understanding attack chains useful for defenders?", options:["Breaking any one stage can disrupt the whole attack","Studying chains speeds up internal email","Knowing them changes the report's colors","Reviewing them helps charge mobile devices"], correct:0, explain:"If defenders block any stage, the attacker's overall plan can fail, so each stage is a chance to stop them.", reward:"Chain Awareness" },
  { id:"attacking-concepts-031", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is reducing public information about staff and systems a useful defense?", options:["It speeds up the network","It encrypts email","It limits the recon data attackers can gather","It disables firewalls"], correct:2, explain:"Less exposed information gives attackers fewer details to plan targeted attacks during reconnaissance.", reward:"Recon Awareness" },
  { id:"attacking-concepts-032", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is a common sign of a phishing email?", options:["Coming from a coworker you personally know","Having no links or attachments at all","Loading noticeably faster than usual","Urgent pressure to click a link or 'verify' your account"], correct:3, explain:"Phishing often uses urgency and a call to click or log in to push victims to act without thinking.", reward:"Phishing Sense" },
  { id:"attacking-concepts-033", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which defense most directly slows brute-force login attempts?", options:["Account lockout or rate limiting after failed attempts","Switching to a brighter monitor screen","Installing a faster main processor","Adding more free disk space"], correct:0, explain:"Locking or throttling accounts after repeated failures stops attackers from guessing endlessly.", reward:"Credential Guard" },
  { id:"attacking-concepts-034", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why does prompt patching reduce exploitation risk?", options:["It hides the system from the network","It removes the vulnerability the exploit relies on","It speeds up the computer's processor","It encrypts all outgoing company email"], correct:1, explain:"If the vulnerability is patched, the matching exploit no longer works, closing that path in.", reward:"Exploit Awareness" },
  { id:"attacking-concepts-035", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is limiting admin rights a defense against privilege escalation?", options:["Limiting them speeds up everyday logins","Doing so changes the desktop theme","It noticeably lowers power usage","Fewer admin accounts means fewer high-value targets to seize"], correct:3, explain:"If few accounts hold admin rights, there are fewer paths for an attacker to reach high privileges.", reward:"Access Guard" },
  { id:"attacking-concepts-036", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is 'credential stuffing'?", options:["A routine method for backing up files","Configuring a single firewall rule","Trying breached username and password pairs against many sites","Running a regular patching process"], correct:2, explain:"Credential stuffing reuses leaked credentials across services, relying on password reuse.", reward:"Credential Guard" },
  { id:"attacking-concepts-037", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do attackers prefer using valid stolen credentials for lateral movement?", options:["Such logins look more colorful in reports","Logging in with real accounts blends in and avoids obvious alarms","Real accounts are noticeably slower to use","Stolen accounts use more power somehow"], correct:1, explain:"Using stolen valid credentials looks like normal activity, helping attackers move quietly.", reward:"Segmentation Sense" },
  { id:"attacking-concepts-038", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers set up persistence?", options:["So they don't lose access if the system restarts or a session ends","Mainly to improve overall system performance","In order to back up important user files","Simply to patch the whole operating system"], correct:0, explain:"Persistence avoids having to re-break in, keeping access available across reboots and over time.", reward:"Persistence Watch" },
  { id:"attacking-concepts-039", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which defense can help disrupt command and control?", options:["Switching to a brighter monitor screen","Installing a faster main processor chip","Blocking or monitoring connections to known-bad destinations","Adding a lot more free disk space"], correct:2, explain:"Blocking outbound traffic to malicious servers cuts the attacker's remote control channel.", reward:"Traffic Watch" },
  { id:"attacking-concepts-040", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which can help limit the impact of data exfiltration?", options:["Switching to a brighter monitor screen","Installing a faster main processor","Adding more memory to the server","Encrypting sensitive data so stolen copies are unreadable"], correct:3, explain:"If exfiltrated data is encrypted and the keys aren't stolen, the thief can't easily read it.", reward:"Data Watch" },
  { id:"attacking-concepts-041", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are reliable backups a key defense against destructive impact like ransomware?", options:["They let you restore data without paying the attacker","They noticeably speed up the computer's CPU","They make the monitor screen much brighter","They block every incoming email message"], correct:0, explain:"Good, tested, isolated backups let you recover from destruction or encryption without paying.", reward:"Impact Sense" },
  { id:"attacking-concepts-042", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is 'pretexting'?", options:["Running a routine data backup process overnight","Inventing a believable story or role to gain trust and information","Configuring one new rule on the firewall","Applying a small patch to fix a bug"], correct:1, explain:"Pretexting uses a fabricated scenario or identity to convince a target to cooperate.", reward:"Human Firewall" },
  { id:"attacking-concepts-043", tier:"Beginner", topic:"Attacking Concepts", prompt:"Cross-site scripting (XSS) involves what?", options:["Backing up the contents of a website","Applying a patch to the web server","Encrypting traffic between the users","Injecting malicious scripts that run in other users' browsers"], correct:3, explain:"XSS injects scripts into a page so they execute in the browsers of other visitors.", reward:"Web Defense" },
  { id:"attacking-concepts-044", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a 'dictionary attack'?", options:["One particular type of scheduled file backup","A single rule applied on the firewall","Guessing passwords from a list of likely words and common choices","Encrypting the entire contents of a disk"], correct:2, explain:"A dictionary attack tries likely words and common passwords rather than every possible combination.", reward:"Credential Guard" },
  { id:"attacking-concepts-045", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is typically an early stage of an attack chain?", options:["Impact","Reconnaissance","Recovery","Backup"], correct:1, explain:"Reconnaissance usually comes early, as attackers gather information before acting.", reward:"Chain Awareness" },
  { id:"attacking-concepts-046", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is an example of reconnaissance?", options:["Looking up a company's employees on a public website","Restoring files from a recent backup","Applying a patch to an internal server","Rotating a user's account password"], correct:0, explain:"Browsing public profiles to learn about staff is information gathering, a form of reconnaissance.", reward:"Recon Awareness" },
  { id:"attacking-concepts-047", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why can 'business email compromise' be especially damaging?", options:["Such attacks only send out bulk spam emails","These messages actually improve email delivery","A trusted account is abused to request fraudulent payments or data","They simply speed up the internal email system"], correct:2, explain:"When a real or spoofed executive account is used, staff may trust fraudulent requests like wire transfers.", reward:"Phishing Sense" },
  { id:"attacking-concepts-048", tier:"Beginner", topic:"Attacking Concepts", prompt:"Brute force isn't only for passwords; what else can it target?", options:["The schedule used for running backups","Color themes shown on the screen","Physical network cables and ports","Encryption keys, by trying many possible keys"], correct:3, explain:"Brute force can also try to guess encryption keys, though strong keys make this infeasible.", reward:"Credential Guard" },
  { id:"attacking-concepts-049", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is the best defense against exploitation of known vulnerabilities?", options:["Keeping systems patched and up to date","Using a brighter screen","Disabling backups","Sharing passwords"], correct:0, explain:"Patching removes known vulnerabilities so their exploits stop working.", reward:"Exploit Awareness" },
  { id:"attacking-concepts-050", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do attackers seek higher privileges after gaining initial access?", options:["Mainly to improve overall performance","Higher rights let them access more data and disable defenses","In order to back up their own files","Simply to patch the operating system"], correct:1, explain:"Elevated privileges let attackers reach sensitive data, move freely, and turn off protections.", reward:"Access Guard" },
  { id:"attacking-concepts-051", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is storing passwords in plain text dangerous?", options:["Plain-text storage is noticeably slower","Such files take up much more disk space","Stored this way it simply looks bad","Anyone who reads the file instantly has every password"], correct:3, explain:"Plain-text passwords are readable as-is, so a single leak exposes all of them; hashing protects them.", reward:"Credential Guard" },
  { id:"attacking-concepts-052", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Which signal might indicate lateral movement?", options:["A monitor that is set to a brighter level","Cooling fans spinning a little bit faster","One account suddenly logging into many systems it never used before","A freshly changed desktop wallpaper image"], correct:2, explain:"An account abruptly accessing unusual hosts can indicate an attacker spreading internally.", reward:"Segmentation Sense" },
  { id:"attacking-concepts-053", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is monitoring auto-start locations useful for defense?", options:["Checking them speeds up system boot","New or unexpected startup entries can reveal persistence","Reviewing them changes the desktop theme","Doing so deletes old log files"], correct:1, explain:"Attackers often hide in startup items, so watching those locations helps spot persistence.", reward:"Persistence Watch" },
  { id:"attacking-concepts-054", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is monitoring outbound (egress) traffic valuable for catching C2?", options:["Compromised hosts must reach out to the attacker, revealing the channel","Watching egress traffic speeds up downloads","Doing so encrypts all outgoing company email","It simply deletes old and unused log files"], correct:0, explain:"C2 requires outbound communication, so watching egress can expose hosts phoning home.", reward:"Traffic Watch" },
  { id:"attacking-concepts-055", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers sometimes compress or split data before exfiltration?", options:["To improve the overall data quality","To create a safe backup of the data","To make transfers smaller or less obvious","To apply a patch to the data files"], correct:2, explain:"Compressing or splitting data can speed transfer and help it slip past simple detection.", reward:"Data Watch" },
  { id:"attacking-concepts-056", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why might an attacker time a destructive attack for a holiday weekend?", options:["Because the weather is usually better then","In order to save electrical power","To make the attack look more colorful","Fewer staff are watching, slowing detection and response"], correct:3, explain:"Reduced staffing during off-hours can delay detection and response, increasing impact.", reward:"Impact Sense" },
  { id:"attacking-concepts-057", tier:"Beginner", topic:"Attacking Concepts", prompt:"What does 'tailgating' (piggybacking) physical access mean?", options:["Following an authorized person through a secure door without badging in","Backing up important data to a remote server","Scanning a whole network for open ports","Encrypting files stored on a shared drive"], correct:0, explain:"Tailgating is slipping into a restricted area behind someone who legitimately opened the door.", reward:"Human Firewall" },
  { id:"attacking-concepts-058", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is keeping web software and plugins updated important?", options:["Updated software simply looks a bit nicer","Known web vulnerabilities get patched, closing common attack paths","Typing on the site feels noticeably faster","The browser then uses noticeably less power"], correct:1, explain:"Many web attacks exploit known flaws in apps or plugins; updates remove those weaknesses.", reward:"Web Defense" },
  { id:"attacking-concepts-059", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why does salting stored password hashes help against precomputed attacks?", options:["Salting noticeably speeds up each login","Doing so changes the desktop theme","It uses up far less disk space overall","A unique salt per password defeats reused precomputed hash tables"], correct:3, explain:"Salts make each hash unique, so attackers can't reuse precomputed tables across accounts.", reward:"Credential Guard" },
  { id:"attacking-concepts-060", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is 'defense in depth' effective against multi-stage attacks?", options:["Relying on a single strong control alone","Requiring no ongoing monitoring at all","Multiple layers give several chances to detect or stop the chain","It noticeably speeds up the whole computer"], correct:2, explain:"Layered defenses mean an attacker must beat several controls, and any one of them may catch them.", reward:"Chain Awareness" },
  { id:"attacking-concepts-061", tier:"Beginner", topic:"Attacking Concepts", prompt:"Port scanning is most associated with which attack stage?", options:["Recovery","Reconnaissance","Backup","Encryption"], correct:1, explain:"Scanning for open ports and services is part of reconnaissance, mapping what a target exposes.", reward:"Recon Awareness" },
  { id:"attacking-concepts-062", tier:"Beginner", topic:"Attacking Concepts", prompt:"What should you do with an unexpected email asking you to urgently log in via a link?", options:["Verify it through a known, separate channel before acting","Click the link in the message right away","Reply directly with your account password","Forward the message to all your coworkers"], correct:0, explain:"Confirm suspicious requests through a trusted, separate channel; don't act on the link itself.", reward:"Phishing Sense" },
  { id:"attacking-concepts-063", tier:"Advanced", topic:"Attacking Concepts", prompt:"How does adding MFA help even if a password is weak against brute force?", options:["Adding it noticeably speeds up each login","Using it hides the account's username","A second factor is still required beyond the guessed password","Turning it on deletes the user account"], correct:2, explain:"MFA requires an additional factor, so a guessed password alone is not enough to log in.", reward:"Credential Guard" },
  { id:"attacking-concepts-064", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are internet-facing services a common exploitation target?", options:["They tend to run a little faster overall","They usually have much nicer interfaces","They generally use far less electrical power","They are reachable by anyone, so flaws there are easy to attack"], correct:3, explain:"Exposed services can be reached from anywhere, so unpatched flaws in them are attractive targets.", reward:"Exploit Awareness" },
  { id:"attacking-concepts-065", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which practice helps detect privilege escalation attempts?", options:["Monitoring and logging changes to admin group membership","Disabling all of the security logs","Sharing admin accounts between staff","Ignoring alerts as they come in"], correct:0, explain:"Watching for unexpected admin-rights changes can reveal an attacker escalating privileges.", reward:"Access Guard" },
  { id:"attacking-concepts-066", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do attackers target cached or stored credentials on a compromised host?", options:["Mainly to free up some disk space","Reusing found credentials helps them move to other systems","In order to speed up the next boot","Simply to patch outdated software"], correct:1, explain:"Harvested credentials let attackers authenticate to additional systems and expand their access.", reward:"Credential Guard" },
  { id:"attacking-concepts-067", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is least privilege a defense against lateral movement?", options:["Limiting access actually speeds up daily logins","Doing so simply changes the desktop theme","It noticeably lowers the overall power use","A compromised account can reach fewer systems if its access is limited"], correct:3, explain:"If each account only has needed access, a stolen one can't reach much, limiting spread.", reward:"Segmentation Sense" },
  { id:"attacking-concepts-068", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is persistence often hidden in legitimate-looking system features?", options:["Mainly to make it run much faster","In order to save electrical power","Blending into normal mechanisms helps it avoid detection","Simply to use a little less disk"], correct:2, explain:"Hiding in normal auto-start or service mechanisms makes malicious persistence harder to notice.", reward:"Persistence Watch" },
  { id:"attacking-concepts-069", tier:"Intermediate", topic:"Attacking Concepts", prompt:"A workstation makes regular, beacon-like connections to an unknown server every few minutes. What might this indicate?", options:["A noticeably faster network link","Possible command-and-control beaconing","Just a routine scheduled backup job","Setting the monitor to a brighter level"], correct:1, explain:"Regular, automated 'beacon' connections to an unknown host can indicate C2 activity.", reward:"Traffic Watch" },
  { id:"attacking-concepts-070", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is monitoring for unusual access to large amounts of sensitive data useful?", options:["Bulk access before exfiltration can be an early warning sign","Watching this speeds up the system disk","Doing so changes the whole desktop theme","It even helps charge the device's battery"], correct:0, explain:"Attackers usually gather data before stealing it, so unusual bulk access can warn defenders early.", reward:"Data Watch" },
  { id:"attacking-concepts-071", tier:"Intermediate", topic:"Attacking Concepts", prompt:"A 'wiper' differs from ransomware because it...?", options:["Quietly restores deleted files","Backs up data to a safe location","Destroys data with no intention of recovery","Encrypts data and demands a ransom"], correct:2, explain:"Wipers aim to destroy data outright, not to extort payment for its return.", reward:"Impact Sense" },
  { id:"attacking-concepts-072", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is security awareness training considered a key defense against social engineering?", options:["Trained people are more likely to recognize and report manipulation","Such training also patches vulnerable servers","It noticeably speeds up all company email","Doing so encrypts every local hard disk"], correct:0, explain:"Since social engineering targets people, aware staff who spot and report it are a strong defense.", reward:"Human Firewall" },
  { id:"attacking-concepts-073", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is using parameterized queries a strong defense against SQL injection?", options:["They make the source code look a lot cleaner","They generally run much faster than normal","They use noticeably less memory on the server","They separate data from commands so input can't change the query's structure"], correct:3, explain:"Parameterized queries treat input strictly as data, so it can't be executed as part of the SQL command.", reward:"Web Defense" },
  { id:"attacking-concepts-074", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why are 'rainbow tables' less effective against properly salted hashes?", options:["Such tables are completely illegal to even use","They are always far too slow to be useful","A per-user salt means a precomputed table won't match the stored hashes","Modern tables need almost no storage at all"], correct:2, explain:"Salting changes each hash, so a generic precomputed (rainbow) table no longer lines up with stored values.", reward:"Credential Guard" },
  { id:"attacking-concepts-075", tier:"Intermediate", topic:"Attacking Concepts", prompt:"An incident shows phishing, then stolen credentials, then data theft. This sequence is an example of what?", options:["A routine data backup plan","The regular software patch cycle","A single firewall rule","An attack chain across multiple stages"], correct:3, explain:"Linked stages from initial access to impact form an attack chain.", reward:"Chain Awareness" },
  { id:"attacking-concepts-076", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why might frequent port scans against your network be worth investigating?", options:["They noticeably improve network speed","They are almost always completely harmless","They can indicate an attacker mapping your exposed services","They quietly back up important data"], correct:2, explain:"Repeated scanning may signal reconnaissance, an early sign someone is probing for weaknesses.", reward:"Recon Awareness" },
  { id:"attacking-concepts-077", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is 'smishing'?", options:["A tool used for backing up files","Phishing carried out over SMS text messages","A device that filters network traffic","One particular type of encryption"], correct:1, explain:"Smishing is phishing delivered by text message, often with a malicious link or fake alert.", reward:"Phishing Sense" },
  { id:"attacking-concepts-078", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is an 'offline' brute-force attack against stolen password hashes?", options:["Guessing rapidly against the stolen hashes without hitting the live system","Calling the user directly to ask them for help","Sending a friendly email to the target victim","Backing up all of the stolen data first"], correct:0, explain:"With stolen hashes, an attacker can guess offline at high speed without triggering account lockouts.", reward:"Credential Guard" },
  { id:"attacking-concepts-079", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is a 'payload' in the context of exploitation?", options:["A saved backup file kept safe for later","One rule that is configured on the firewall","The action or code that runs after a vulnerability is exploited","A secret password used for an account"], correct:2, explain:"The payload is what the exploit delivers or executes once it has gained a foothold.", reward:"Exploit Awareness" },
  { id:"attacking-concepts-080", tier:"Intermediate", topic:"Attacking Concepts", prompt:"An attacker abuses a misconfigured service running as admin. What did this enable?", options:["A noticeably faster processor","One extra scheduled backup","A freshly applied desktop theme","Privilege escalation to admin-level access"], correct:3, explain:"Abusing a high-privilege service can hand the attacker that service's elevated rights.", reward:"Access Guard" },
  { id:"attacking-concepts-081", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which helps protect credentials even if a password is stolen?", options:["Multi-factor authentication (MFA)","A brighter screen","A faster CPU","Disabling logs"], correct:0, explain:"MFA requires an extra factor, so a stolen password alone usually isn't enough to log in.", reward:"Credential Guard" },
  { id:"attacking-concepts-082", tier:"Beginner", topic:"Attacking Concepts", prompt:"Lateral movement happens at which point of an attack?", options:["Before any access has been gained at all","After an initial foothold, to expand inside the network","Only while backups are actively running","It essentially never happens in practice"], correct:1, explain:"Lateral movement follows initial access, as the attacker expands to more internal systems.", reward:"Segmentation Sense" },
  { id:"attacking-concepts-083", tier:"Beginner", topic:"Attacking Concepts", prompt:"Removing attacker persistence is important because otherwise...?", options:["The monitor screen slowly begins to dim","Stored backups just keep growing larger","The processor slowly begins to overheat","The attacker can regain access even after you think you cleaned up"], correct:3, explain:"If persistence remains, the attacker simply comes back, so it must be found and removed.", reward:"Persistence Watch" },
  { id:"attacking-concepts-084", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why can DNS sometimes be abused for command and control?", options:["DNS is generally a very slow protocol to use here","DNS responses are unusually colorful to read","DNS requests are often allowed out, so data or commands can be smuggled in them","DNS uses no real network connection at all here"], correct:2, explain:"Because DNS traffic is usually permitted, attackers sometimes hide C2 communication inside DNS queries.", reward:"Traffic Watch" },
  { id:"attacking-concepts-085", tier:"Beginner", topic:"Attacking Concepts", prompt:"Data loss prevention (DLP) tools mainly help to do what?", options:["Speed up the whole office Wi-Fi network","Detect or block sensitive data from leaving the organization","Patch all of the organization's servers","Back up the local disks every single night"], correct:1, explain:"DLP watches for sensitive data moving out and can alert on or block exfiltration.", reward:"Data Watch" },
  { id:"attacking-concepts-086", tier:"Beginner", topic:"Attacking Concepts", prompt:"Denial of service (DoS) impact mainly does what?", options:["Makes a service unavailable by overwhelming it","Steals stored account passwords","Backs up data to the cloud","Patches outdated software flaws"], correct:0, explain:"A DoS overwhelms a system or network so legitimate users can't use it.", reward:"Impact Sense" },
  { id:"attacking-concepts-087", tier:"Beginner", topic:"Attacking Concepts", prompt:"An attacker leaves infected USB drives in a parking lot hoping someone plugs one in. This is called?", options:["Patching","Baiting","Backing up","Scanning"], correct:1, explain:"Baiting tempts victims with something like a 'free' USB that delivers malware when used.", reward:"Human Firewall" },
  { id:"attacking-concepts-088", tier:"Intermediate", topic:"Attacking Concepts", prompt:"A login form lets you submit ' OR '1'='1 and logs you in. What weakness is this?", options:["Some kind of backup configuration error","A firewall that has been misconfigured","A basic DNS name resolution problem","SQL injection due to unsafe handling of input"], correct:3, explain:"Input changing the query's logic indicates SQL injection from unsafe input handling.", reward:"Web Defense" },
  { id:"attacking-concepts-089", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which most improves resistance to password guessing attacks?", options:["Long, unique passwords plus MFA","A brighter screen","A faster CPU","More disk space"], correct:0, explain:"Length, uniqueness, and a second factor together make guessing or reusing passwords far harder.", reward:"Credential Guard" },
  { id:"attacking-concepts-090", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do mature defenders aim to detect attacks at the earliest possible stage?", options:["It mainly produces much nicer reports","Early detection stops the attacker before they reach high-impact goals","To deliberately use up more electrical power","To intentionally slow the whole network down"], correct:1, explain:"Catching an attack early, such as at recon or initial access, prevents the costly later stages.", reward:"Chain Awareness" },
  { id:"attacking-concepts-091", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is 'active reconnaissance'?", options:["Reading publicly available records found online","Running a routine scheduled data backup process","Generating a brand new encryption key pair","Directly probing the target's systems, such as scanning, which can be detected"], correct:3, explain:"Active recon interacts with the target, for example by scanning, which is more detectable than passive recon.", reward:"Recon Awareness" },
  { id:"attacking-concepts-092", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers often register lookalike domains (like examp1e.com)?", options:["To improve overall network speed","For making routine data backups","To trick users into trusting a fake site or sender","To patch outdated software flaws"], correct:2, explain:"Lookalike domains mimic real ones so victims trust phishing pages or emails.", reward:"Phishing Sense" },
  { id:"attacking-concepts-093", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are default or common passwords risky against brute force?", options:["They tend to use up more power","They are tried first because they are well known","They are always stored encrypted","They usually load more slowly"], correct:1, explain:"Common and default passwords are at the top of attackers' guess lists, so they fall quickly.", reward:"Credential Guard" },
  { id:"attacking-concepts-094", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is reducing the number of exposed services (attack surface) helpful?", options:["Fewer services means fewer things an attacker can try to exploit","Making the whole office Wi-Fi run faster","Changing the desktop's visual color theme","It deletes old and unused system log files"], correct:0, explain:"A smaller attack surface gives attackers fewer potential vulnerabilities to exploit.", reward:"Exploit Awareness" },
  { id:"attacking-concepts-095", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is keeping software patched also a defense against privilege escalation?", options:["Quietly hiding the existing user accounts","Noticeably speeding up the whole GPU","Many escalation techniques abuse unpatched local vulnerabilities","It deletes the existing system backups"], correct:2, explain:"Some privilege-escalation methods exploit local bugs, so patching removes those opportunities.", reward:"Access Guard" },
  { id:"attacking-concepts-096", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is a password manager helpful against credential theft across sites?", options:["It shows passwords in bright colors","It can help charge nearby devices","It noticeably speeds up office Wi-Fi","It makes using a unique strong password per site practical"], correct:3, explain:"Unique strong passwords per site limit damage from any single breach; a manager makes that practical.", reward:"Credential Guard" },
  { id:"attacking-concepts-097", tier:"Beginner", topic:"Attacking Concepts", prompt:"After gaining a foothold, an attacker tries to reach the file server from a workstation. This attempt is an example of what?", options:["Lateral movement","A backup","A patch","Reconnaissance only"], correct:0, explain:"Trying to reach other internal systems from a foothold is lateral movement.", reward:"Segmentation Sense" },
  { id:"attacking-concepts-098", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why might an attacker create a new hidden user account on a compromised system?", options:["Mainly to improve system performance","As a persistence method to keep a way back in","In order to back up important files","Simply to patch the whole system"], correct:1, explain:"A hidden account gives the attacker a durable way to log back in, a form of persistence.", reward:"Persistence Watch" },
  { id:"attacking-concepts-099", tier:"Beginner", topic:"Attacking Concepts", prompt:"Cutting off command and control during an incident helps to do what?", options:["Speed up the computer's main processor","Brighten the monitor's whole display","Add some more free disk space","Stop the attacker from controlling compromised machines"], correct:3, explain:"Severing C2 removes the attacker's remote control, limiting further damage.", reward:"Traffic Watch" },
  { id:"attacking-concepts-100", tier:"Beginner", topic:"Attacking Concepts", prompt:"Exfiltration typically happens at which point in an attack?", options:["Before any access has been gained","During the very first network scan","After the attacker has reached the valuable data","Only while backups are running"], correct:2, explain:"Exfiltration comes after attackers locate and access the data they want to steal.", reward:"Data Watch" },
  { id:"attacking-concepts-104", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why can reconnaissance be valuable to an attacker?", options:["It automatically gives admin access","It prevents defenders from logging events","It replaces malware completely","It helps identify targets, technologies, users, and possible weaknesses"], correct:3, explain:"Recon helps attackers choose where and how to focus later activity.", reward:"Recon Basics" },
  { id:"attacking-concepts-105", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is OSINT?", options:["Open-source intelligence gathered from publicly available sources","A password cracking tool only","A private firewall rule","A malware persistence method"], correct:0, explain:"OSINT uses public information such as websites, documents, job posts, and records.", reward:"OSINT Sense" },
  { id:"attacking-concepts-106", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is an example of OSINT?", options:["Breaking into a server","Reading public job posts to learn used technologies","Deleting endpoint logs","Installing a backdoor"], correct:1, explain:"Public job posts can reveal technologies and skills used by an organization.", reward:"OSINT Sense" },
  { id:"attacking-concepts-107", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why can public employee information be useful to attackers?", options:["It makes malware unnecessary","It patches systems automatically","It can support phishing, impersonation, or targeting","It disables MFA"], correct:2, explain:"Names, roles, and contact details can help attackers craft believable lures.", reward:"OSINT Sense" },
  { id:"attacking-concepts-110", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is spear phishing?", options:["A phishing email sent to everyone randomly","A targeted phishing attempt tailored to a specific person or group","A firewall configuration method","A backup restore process"], correct:1, explain:"Spear phishing uses target-specific context to seem more believable.", reward:"Phishing Basics" },
  { id:"attacking-concepts-111", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is credential theft?", options:["Changing a hostname","Installing software updates","Stealing usernames, passwords, tokens, or keys","Creating a backup copy"], correct:2, explain:"Credential theft gives attackers ways to access accounts or systems.", reward:"Credential Theft" },
  { id:"attacking-concepts-112", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are stolen credentials dangerous?", options:["They make systems faster","They prevent all attacks","They delete user accounts automatically","They may allow attackers to log in as legitimate users"], correct:3, explain:"Valid credentials can bypass many simple security checks.", reward:"Credential Theft" },
  { id:"attacking-concepts-113", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is password spraying?", options:["Trying a small number of common passwords across many accounts","Changing passwords for every user","Encrypting password databases","Backing up passwords securely"], correct:0, explain:"Password spraying avoids many attempts on one account and instead tries common passwords broadly.", reward:"Password Attacks" },
  { id:"attacking-concepts-114", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is brute forcing?", options:["Reviewing access logs","Trying many possible passwords or values until one works","Installing a patch","Creating a security policy"], correct:1, explain:"Brute forcing attempts many possibilities, often automatically.", reward:"Password Attacks" },
  { id:"attacking-concepts-116", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why does password reuse help attackers?", options:["It makes encryption stronger","It prevents credential stuffing","It disables account lockout","One leaked password may work on multiple services"], correct:3, explain:"Reused passwords increase the impact of one breach.", reward:"Password Attacks" },
  { id:"attacking-concepts-117", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is exploitation?", options:["Using a weakness to cause unintended behavior or gain access","Creating user training","Installing official updates","Writing a backup plan"], correct:0, explain:"Exploitation means taking advantage of a vulnerability or weakness.", reward:"Exploit Basics" },
  { id:"attacking-concepts-118", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a vulnerability exploit?", options:["A normal user login","A method that abuses a known weakness","A password manager","A backup schedule"], correct:1, explain:"An exploit is a technique or code path that takes advantage of a vulnerability.", reward:"Exploit Basics" },
  { id:"attacking-concepts-119", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is initial access?", options:["A final incident report","A backup restore","The first foothold an attacker gains in an environment","A DNS record update"], correct:2, explain:"Initial access is the entry point into a system or network.", reward:"Initial Access" },
  { id:"attacking-concepts-120", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is an example of initial access?", options:["Writing a lessons-learned report","Testing backup restoration","Updating antivirus signatures","A phishing email leading to a compromised account"], correct:3, explain:"Phishing is a common way attackers may gain initial access.", reward:"Initial Access" },
  { id:"attacking-concepts-121", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is malware?", options:["Software designed to perform unwanted or harmful actions","A normal patch file","A secure configuration baseline","A backup archive"], correct:0, explain:"Malware includes malicious programs such as trojans, ransomware, and spyware.", reward:"Malware Basics" },
  { id:"attacking-concepts-122", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is ransomware?", options:["A password manager","Malware that encrypts or blocks access to data and demands payment","A secure backup method","A network monitoring tool"], correct:1, explain:"Ransomware tries to pressure victims by denying access to data or systems.", reward:"Ransomware Sense" },
  { id:"attacking-concepts-123", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is spyware?", options:["A firewall rule","A patch management tool","Software that secretly collects information from a device or user","A DNS server"], correct:2, explain:"Spyware is designed to monitor and collect information without proper consent.", reward:"Spyware Sense" },
  { id:"attacking-concepts-124", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a trojan?", options:["A backup copy of a server","A secure admin account","A network cable type","Malware disguised as something legitimate or useful"], correct:3, explain:"Trojans rely on deception to get installed or executed.", reward:"Trojan Sense" },
  { id:"attacking-concepts-126", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is an example of persistence?", options:["A user changing their wallpaper","A scheduled task that runs attacker-controlled code","A normal backup restore","A DNS cache refresh"], correct:1, explain:"Scheduled tasks can be abused to run code repeatedly or after login.", reward:"Persistence Basics" },
  { id:"attacking-concepts-128", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is privilege escalation valuable to attackers?", options:["It makes logs easier to read","It prevents malware execution","It removes the need for credentials","Higher privileges can allow broader access and control"], correct:3, explain:"More privilege usually means greater ability to change systems or access data.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-130", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers perform lateral movement?", options:["To improve backup quality","To reach more valuable systems, accounts, or data","To make dashboards prettier","To reduce their own access"], correct:1, explain:"Attackers often move laterally to find higher-value targets.", reward:"Lateral Movement" },
  { id:"attacking-concepts-131", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is command and control?", options:["A password reset process","A firewall policy review","Communication between compromised systems and attacker-controlled infrastructure","A backup scheduling method"], correct:2, explain:"Command and control lets attackers send instructions or receive data.", reward:"C2 Basics" },
  { id:"attacking-concepts-132", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is beaconing?", options:["A normal monitor sleep setting","Only a DNS update","Only a firewall backup","Repeated check-ins from a system to an external destination"], correct:3, explain:"Beaconing can indicate malware or an agent contacting command infrastructure.", reward:"Beaconing Sense" },
  { id:"attacking-concepts-133", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is exfiltration?", options:["Moving data out of an environment without authorization","Restoring files from backup","Installing updates","Resetting a password"], correct:0, explain:"Exfiltration is unauthorized data transfer out of a system or organization.", reward:"Exfil Basics" },
  { id:"attacking-concepts-134", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is data staging used by attackers?", options:["To patch files safely","To collect or prepare data before exfiltration","To improve backups","To encrypt logs for defenders"], correct:1, explain:"Staging places data where it can be compressed, packaged, or transferred.", reward:"Exfil Basics" },
  { id:"attacking-concepts-135", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is defense evasion?", options:["Improving firewall rules","Creating user training","Trying to avoid detection or security controls","Backing up logs"], correct:2, explain:"Defense evasion includes hiding activity or disabling protections.", reward:"Evasion Basics" },
  { id:"attacking-concepts-136", tier:"Beginner", topic:"Attacking Concepts", prompt:"Which is an example of defense evasion?", options:["Writing a clear incident report","Installing a security update","Enabling MFA","Disabling security logging or endpoint protection"], correct:3, explain:"Disabling defenses can help attackers avoid detection.", reward:"Evasion Basics" },
  { id:"attacking-concepts-137", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is log tampering?", options:["Changing or deleting logs to hide activity","Centralizing logs securely","Testing a detection rule","Creating a backup"], correct:0, explain:"Attackers may try to alter logs to reduce evidence.", reward:"Log Tampering" },
  { id:"attacking-concepts-138", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is obfuscation?", options:["Making code easier to read","Making code, commands, or data harder to understand","Deleting all files","Creating a firewall rule"], correct:1, explain:"Obfuscation can hide intent from analysts or tools.", reward:"Obfuscation Sense" },
  { id:"attacking-concepts-139", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why might attackers encode commands?", options:["Encoding always makes commands harmless","Encoding prevents execution","To hide or make command content harder to inspect","To patch the operating system"], correct:2, explain:"Encoding can be legitimate, but attackers may use it to obscure commands.", reward:"Obfuscation Sense" },
  { id:"attacking-concepts-140", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is living off the land?", options:["Using only custom malware","Avoiding computers completely","Using only physical access","Abusing legitimate built-in tools for attacker goals"], correct:3, explain:"Living-off-the-land techniques use trusted tools in suspicious ways.", reward:"LOLBins Sense" },
  { id:"attacking-concepts-141", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are built-in admin tools attractive to attackers?", options:["They are often trusted, available, and may blend with normal admin activity","They cannot run commands","They are never logged","They only work offline"], correct:0, explain:"Legitimate tools can be abused while looking less suspicious at first glance.", reward:"LOLBins Sense" },
  { id:"attacking-concepts-142", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a payload in attack terminology?", options:["A backup disk","Code or content delivered to perform an action","A user awareness poster","A patch note"], correct:1, explain:"A payload is the part intended to execute, exploit, or perform a task.", reward:"Payload Sense" },
  { id:"attacking-concepts-143", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a dropper?", options:["A firewall update","A backup tool","A program or script that delivers or installs another malicious component","A password policy"], correct:2, explain:"Droppers are used to place additional malware or tools on a system.", reward:"Malware Chain" },
  { id:"attacking-concepts-144", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a downloader in malware activity?", options:["A user installing official updates","A firewall log parser","A password manager","A component that retrieves additional content from another location"], correct:3, explain:"Downloaders fetch additional payloads, tools, or instructions.", reward:"Malware Chain" },
  { id:"attacking-concepts-145", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a backdoor?", options:["A hidden or unauthorized way to regain access","A secure password manager","A normal firewall update","A system backup"], correct:0, explain:"Backdoors provide access that bypasses normal expected paths.", reward:"Backdoor Sense" },
  { id:"attacking-concepts-146", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are backdoors dangerous?", options:["They improve patching","They can allow continued access even after the initial issue seems fixed","They prevent all lateral movement","They only affect printers"], correct:1, explain:"Backdoors can survive incomplete cleanup and enable re-entry.", reward:"Backdoor Sense" },
  { id:"attacking-concepts-147", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a web shell?", options:["A browser theme","A secure website backup","A malicious or unauthorized script that allows remote control through a web server","A DNS record type"], correct:2, explain:"Web shells let attackers send commands through a compromised web application or server.", reward:"Web Shell Sense" },
  { id:"attacking-concepts-148", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are web shells useful to attackers?", options:["They block all user access","They patch web servers automatically","They replace firewalls","They may provide persistent remote command access through web traffic"], correct:3, explain:"Web shells can blend with web traffic and provide ongoing access.", reward:"Web Shell Sense" },
  { id:"attacking-concepts-149", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a vulnerability scan from an attacker's point of view?", options:["A way to identify exposed weaknesses or services","A backup verification process","A user training method","A secure encryption routine"], correct:0, explain:"Scanning can reveal where exploitation might be possible.", reward:"Scanning Sense" },
  { id:"attacking-concepts-150", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is port scanning used to discover?", options:["User birthdays","Open services on a target system","Backup schedules","Screen resolution"], correct:1, explain:"Port scanning identifies reachable network services.", reward:"Scanning Sense" },
  { id:"attacking-concepts-151", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is service enumeration useful to attackers?", options:["It deletes exposed services","It identifies software, versions, and possible attack paths","It patches vulnerabilities automatically","It replaces phishing"], correct:1, explain:"Enumeration gives attackers technical details for later decisions.", reward:"Enumeration Sense" },
  { id:"attacking-concepts-152", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is banner grabbing?", options:["Changing a website banner image","Collecting service information revealed by network services","Creating a phishing email","Encrypting a hard drive"], correct:1, explain:"Banners may reveal service names, versions, or configurations.", reward:"Enumeration Sense" },
  { id:"attacking-concepts-153", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why can software version information be risky when exposed?", options:["Versions are always harmless","Version numbers prevent attacks","Attackers may match versions to known vulnerabilities","Versions disable exploit attempts"], correct:2, explain:"Public version details can help attackers choose relevant exploits.", reward:"Exposure Sense" },
  { id:"attacking-concepts-154", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is an attack chain?", options:["A list of firewall vendors","A password reset workflow","A backup rotation schedule","A sequence of attacker steps from initial access to objectives"], correct:3, explain:"Attack chains help defenders understand progression across stages.", reward:"Attack Chain" },
  { id:"attacking-concepts-155", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers often combine multiple techniques?", options:["One technique may only provide partial access or limited progress","Multiple techniques prevent all detection","Using more techniques always reduces risk","Techniques cannot be chained"], correct:0, explain:"Attackers may chain recon, access, persistence, privilege escalation, and exfiltration.", reward:"Attack Chain" },
  { id:"attacking-concepts-156", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is an exploit chain?", options:["A list of passwords","Multiple weaknesses or steps combined to reach a goal","A backup sequence","A secure patch workflow"], correct:1, explain:"Exploit chains combine multiple issues to increase impact.", reward:"Exploit Basics" },
  { id:"attacking-concepts-157", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why can low-severity issues become serious when chained?", options:["Low severity always means no risk","Chaining is impossible","Several small weaknesses can combine into a high-impact path","Low issues cannot affect security"], correct:2, explain:"Attack paths often depend on multiple small gaps.", reward:"Attack Path" },
  { id:"attacking-concepts-158", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is an attack path?", options:["A visual theme in a game","A deleted alert","A backup route","A route an attacker could take from entry point to valuable target"], correct:3, explain:"Attack paths show how weaknesses connect to create risk.", reward:"Attack Path" },
  { id:"attacking-concepts-159", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is privilege escalation often pursued after initial access?", options:["Initial access is often limited and higher privileges unlock more actions","Privilege escalation deletes logs automatically","Higher privileges make attackers easier to detect every time","It prevents lateral movement"], correct:0, explain:"Attackers often need more permissions to reach objectives.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-160", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is horizontal privilege escalation?", options:["Gaining administrator access from a normal account","Accessing another account or resource at a similar privilege level","Deleting all accounts","Patching a vulnerability"], correct:1, explain:"Horizontal escalation moves across users or resources without necessarily gaining higher privilege.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-161", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is vertical privilege escalation?", options:["Accessing a different user at the same level","Logging out of a system","Gaining higher privilege than originally available","Restoring a backup"], correct:2, explain:"Vertical escalation means moving from lower to higher privilege.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-162", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are misconfigurations useful to attackers?", options:["Misconfigurations always improve security","Misconfigurations prevent all attacks","Misconfigurations remove need for credentials","They may expose access, data, services, or weak permissions"], correct:3, explain:"Many attacks abuse configuration mistakes rather than new vulnerabilities.", reward:"Misconfig Abuse" },
  { id:"attacking-concepts-163", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is credential dumping?", options:["Extracting credentials or credential material from a system","Changing all passwords securely","Deleting old user profiles","Creating MFA prompts"], correct:0, explain:"Credential dumping tries to obtain passwords, hashes, tokens, or keys.", reward:"Credential Theft" },
  { id:"attacking-concepts-164", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is credential dumping high impact?", options:["Credentials cannot be reused","Captured credentials can enable lateral movement and privilege escalation","It only affects screen settings","It prevents persistence"], correct:1, explain:"Stolen credentials can expand attacker access.", reward:"Credential Theft" },
  { id:"attacking-concepts-165", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is pass-the-hash conceptually?", options:["Resetting a password hash","Encrypting a password safely","Using a password hash as authentication material without knowing the plaintext password","Deleting password history"], correct:2, explain:"Pass-the-hash abuses credential material directly for authentication.", reward:"Credential Theft" },
  { id:"attacking-concepts-166", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are tokens valuable to attackers?", options:["Tokens cannot be used for access","Tokens always expire instantly","Tokens are only visual labels","Tokens may grant access without requiring the password again"], correct:3, explain:"Session or access tokens can let attackers act as a user or service.", reward:"Token Theft" },
  { id:"attacking-concepts-167", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is session hijacking?", options:["Taking over or abusing an existing authenticated session","Installing official updates","Creating a firewall rule","Backing up user files"], correct:0, explain:"Session hijacking bypasses normal login by abusing an existing session.", reward:"Token Theft" },
  { id:"attacking-concepts-168", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is MFA not always enough against token theft?", options:["MFA never works","A stolen active token may bypass repeated password and MFA prompts","MFA disables sessions","Tokens cannot be stolen"], correct:1, explain:"MFA protects login, but active session tokens also need protection.", reward:"Token Theft" },
  { id:"attacking-concepts-169", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is persistence through account creation?", options:["Deleting all users","Changing firewall rules","Creating or enabling an account to maintain access","Installing browser updates"], correct:2, explain:"An attacker may create an account so they can return later.", reward:"Persistence Basics" },
  { id:"attacking-concepts-170", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is persistence through mailbox rules?", options:["Making email load faster","Deleting phishing emails","Changing the user's password","Creating rules that forward or hide emails after account compromise"], correct:3, explain:"Mailbox rules can help attackers monitor mail or hide security notifications.", reward:"Email Persistence" },
  { id:"attacking-concepts-171", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers create hidden or disguised files?", options:["To avoid user or defender attention","To make files easier to find","To improve patching","To disable backups"], correct:0, explain:"Hiding or disguising files can support evasion and persistence.", reward:"Evasion Basics" },
  { id:"attacking-concepts-172", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is masquerading?", options:["Using a misleading name, path, or appearance to look legitimate","Disabling a keyboard","Backing up a database","Updating a browser"], correct:0, explain:"Masquerading tries to make suspicious items look normal.", reward:"Masquerading" },
  { id:"attacking-concepts-173", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is masquerading effective?", options:["Users and tools may trust names or paths that look familiar","It prevents all logging","It patches systems","It removes the need for execution"], correct:0, explain:"Familiar-looking names can reduce suspicion.", reward:"Masquerading" },
  { id:"attacking-concepts-174", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is process injection conceptually?", options:["Changing a password policy","Backing up a process list","Hiding or running code inside another process","Creating a DNS record"], correct:2, explain:"Process injection can hide malicious code in or behind another process.", reward:"Evasion Basics" },
  { id:"attacking-concepts-175", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers use encrypted communication?", options:["Encrypted traffic always proves legitimacy","To protect their own communication from easy inspection","To patch C2 servers","To prevent all beaconing"], correct:1, explain:"Encryption can hide payload contents from simple network inspection.", reward:"C2 Basics" },
  { id:"attacking-concepts-176", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is domain generation algorithm behavior?", options:["Creating backups by domain name","Generating many domain names for command-and-control resilience","Deleting DNS logs","Patching DNS servers"], correct:1, explain:"DGAs can help malware find attacker infrastructure even if domains are blocked.", reward:"C2 Basics" },
  { id:"attacking-concepts-177", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers use commonly allowed ports like 443?", options:["Port 443 cannot be monitored","It may blend with normal HTTPS traffic","It prevents all detection","It disables firewalls"], correct:1, explain:"Using common ports can make malicious traffic look less unusual.", reward:"C2 Basics" },
  { id:"attacking-concepts-178", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is DNS tunneling conceptually?", options:["Using DNS traffic to carry hidden data or communication","Creating a normal A record","Disabling DNS","Encrypting local files"], correct:0, explain:"DNS tunneling abuses a common protocol as a covert channel.", reward:"DNS Tunneling" },
  { id:"attacking-concepts-179", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why can cloud storage be abused in attacks?", options:["Cloud storage cannot hold files","It may be used for staging, payload delivery, or exfiltration","Cloud storage prevents all malware","It is never logged"], correct:1, explain:"Legitimate cloud platforms can be abused to host or move data.", reward:"Cloud Abuse" },
  { id:"attacking-concepts-180", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is data exfiltration through legitimate services?", options:["Only using malware-specific servers","Using trusted platforms to move data out and blend with normal traffic","Deleting all data locally","Restoring data from backups"], correct:1, explain:"Attackers may abuse common services because they are often allowed.", reward:"Exfil Basics" },
  { id:"attacking-concepts-181", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is staging data before exfiltration useful to attackers?", options:["It prevents data theft","It deletes all files automatically","It allows collection, compression, filtering, or packaging before transfer","It improves endpoint security"], correct:2, explain:"Staging prepares data for easier transfer or handling.", reward:"Exfil Basics" },
  { id:"attacking-concepts-182", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is collection in an attack lifecycle?", options:["Gathering target data of interest before use or exfiltration","Installing a security patch","Deleting a detection rule","Updating firewall firmware"], correct:0, explain:"Collection focuses on gathering the data attackers want.", reward:"Collection Sense" },
  { id:"attacking-concepts-183", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers compress or archive stolen data?", options:["To make the data harder to transfer","To package many files and sometimes reduce size before exfiltration","To patch the files","To prevent access"], correct:1, explain:"Compression and archives make staging and transfer easier.", reward:"Collection Sense" },
  { id:"attacking-concepts-184", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is impact in an attack lifecycle?", options:["Only a login attempt","Only reconnaissance","Actions that disrupt, destroy, encrypt, manipulate, or expose systems or data","Only reading public websites"], correct:2, explain:"Impact describes the harm or final effect of attacker activity.", reward:"Impact Sense" },
  { id:"attacking-concepts-185", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Which is an example of impact?", options:["Reading a public job post","Encrypting files with ransomware","Looking up a company website","Scanning a single open port"], correct:1, explain:"Ransomware encryption is a direct impact action.", reward:"Impact Sense" },
  { id:"attacking-concepts-186", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is it risky to treat one attack technique as isolated?", options:["Attackers may chain techniques across access, execution, persistence, privilege, and impact","Techniques can never connect","One alert always shows the whole incident","Attackers only perform one action"], correct:0, explain:"Attackers often progress through multiple linked stages.", reward:"Attack Chain" },
  { id:"attacking-concepts-187", tier:"Advanced", topic:"Attacking Concepts", prompt:"A phishing email leads to PowerShell execution, then outbound beaconing. What does this suggest?", options:["Only a normal software update","A possible attack chain from initial access to execution and command-and-control","A harmless DNS lookup","A successful backup"], correct:1, explain:"Multiple connected behaviors raise concern beyond a single event.", reward:"Attack Chain" },
  { id:"attacking-concepts-188", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is attacker objective important to understand?", options:["Objectives are irrelevant to defenders","Objectives replace evidence","Understanding goals helps predict likely next steps and targets","Objectives prove attribution"], correct:2, explain:"Objectives help defenders anticipate collection, movement, or impact behavior.", reward:"Threat Thinking" },
  { id:"attacking-concepts-189", tier:"Advanced", topic:"Attacking Concepts", prompt:"A low-privilege account accesses a file share, finds admin scripts with secrets, then reaches servers. What concept does this show?", options:["Only normal browsing","Only endpoint patching","A harmless backup","An attack path created by weak secret handling and access control"], correct:3, explain:"Small weaknesses can chain into high-impact access.", reward:"Attack Path" },
  { id:"attacking-concepts-190", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is least privilege an effective defense against attack paths?", options:["It limits what attackers can reach with one compromised account","It prevents every phishing email","It makes passwords unnecessary","It disables all software bugs"], correct:0, explain:"Least privilege reduces attacker options after compromise.", reward:"Attack Path" },
  { id:"attacking-concepts-191", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is detection of living-off-the-land activity difficult?", options:["Built-in tools cannot be logged","The same tools may be used legitimately by administrators","Living-off-the-land always uses unknown malware","It only happens on Linux"], correct:1, explain:"Context is needed to distinguish normal administration from abuse.", reward:"LOLBins Sense" },
  { id:"attacking-concepts-192", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the defensive value of understanding attacker techniques?", options:["It helps defenders build detections, controls, and investigations around real behavior","It teaches defenders to ignore alerts","It replaces patching","It removes the need for logs"], correct:0, explain:"Understanding attacker behavior makes defense more practical and focused.", reward:"Defense Thinking" },
  { id:"attacking-concepts-193", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why are identity attacks often high impact?", options:["Identity systems cannot be logged","Identity attacks only affect email signatures","Identity compromise can grant access across many systems and services","Identity attacks prevent lateral movement"], correct:2, explain:"Modern environments often rely heavily on identity for access control.", reward:"Identity Attack" },
  { id:"attacking-concepts-194", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why are cloud tokens and API keys valuable to attackers?", options:["They cannot be used for access","They are only decorative","They expire before use every time","They may allow direct access to cloud resources and automation"], correct:3, explain:"Cloud credentials can provide powerful access outside normal interactive login.", reward:"Cloud Attack" },
  { id:"attacking-concepts-195", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is a common goal after compromising cloud credentials?", options:["Enumerate resources, permissions, data, and possible persistence paths","Make the cloud environment more secure","Delete the attacker's access immediately","Install local printer drivers"], correct:0, explain:"Attackers often explore cloud environments to understand access and value.", reward:"Cloud Attack" },
  { id:"attacking-concepts-196", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why can attacker use of legitimate cloud services be hard to detect?", options:["Cloud services cannot be monitored","Traffic may look like normal business use unless context is checked","Cloud services never host malicious content","Legitimate services block all abuse"], correct:1, explain:"Abuse of trusted platforms can blend with expected activity.", reward:"Cloud Abuse" },
  { id:"attacking-concepts-197", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why should defenders think in terms of behavior instead of only tool names?", options:["Tool names never matter","Behavior is always impossible to detect","Attackers can rename tools or switch tools while keeping similar behavior","Behavior removes the need for alerts"], correct:2, explain:"Behavior-based thinking is harder for attackers to bypass than name-only detection.", reward:"Behavior Thinking" },
  { id:"attacking-concepts-198", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the risk of focusing only on known indicators?", options:["Known indicators catch every future attack","Indicators never expire","Indicators replace behavior analysis","Attackers can change infrastructure, filenames, hashes, or domains"], correct:3, explain:"Indicators are useful, but attacker behavior and tradecraft matter too.", reward:"Behavior Thinking" },
  { id:"attacking-concepts-199", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why should defenders map attacker behavior to controls?", options:["It shows which defenses prevent, detect, or respond to each stage","Mapping makes attackers stronger","Controls cannot affect behavior","Mapping replaces incident response"], correct:0, explain:"Mapping behavior to controls helps identify defensive gaps.", reward:"Defense Thinking" },
  { id:"attacking-concepts-200", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the strongest reason for blue teamers to study attacking concepts?", options:["To understand attacker behavior well enough to detect, prevent, and respond effectively","To ignore defensive controls","To make all attacks legal","To stop using logs"], correct:0, explain:"Defenders study attack concepts to improve practical defense.", reward:"Defense Thinking" },
  { id:"attacking-concepts-201", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is scanning in an attack context?", options:["Probing systems to discover hosts, ports, services, or weaknesses","Restoring data from backup","Writing security policy","Changing a user's display name"], correct:0, explain:"Scanning helps attackers understand what is reachable and potentially vulnerable.", reward:"Scanning Sense" },
  { id:"attacking-concepts-202", tier:"Beginner", topic:"Attacking Concepts", prompt:"What does service enumeration try to discover?", options:["Only the user's favorite browser","Details about running services such as software, version, or configuration","The color of a network cable","A backup restore point"], correct:1, explain:"Enumeration gathers details that can guide later attack steps.", reward:"Enumeration Sense" },
  { id:"attacking-concepts-203", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are exposed services useful to attackers?", options:["They always block attackers","They cannot contain vulnerabilities","They may provide reachable entry points or information","They disable all logging"], correct:2, explain:"Reachable services increase possible attack surface.", reward:"Attack Surface" },
  { id:"attacking-concepts-204", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is an exposed attack surface?", options:["A secure backup only","A user training page","A disabled system account","Systems, services, or paths reachable by an attacker"], correct:3, explain:"Attack surface is what can be targeted or interacted with.", reward:"Attack Surface" },
  { id:"attacking-concepts-205", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a web vulnerability?", options:["A weakness in a website or web application that can be abused","A normal browser bookmark","A secure password policy","A backup schedule"], correct:0, explain:"Web vulnerabilities can allow actions such as data access, account takeover, or code execution.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-206", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is SQL injection conceptually?", options:["Backing up a database","Injecting unwanted database commands through unsafe input handling","Encrypting SQL backups","Installing a database patch"], correct:1, explain:"SQL injection happens when input is treated as database instructions.", reward:"Injection Sense" },
  { id:"attacking-concepts-207", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is cross-site scripting conceptually?", options:["Changing a firewall rule","Running a backup job","Injecting script into web pages viewed by users","Installing a browser update"], correct:2, explain:"XSS abuses web applications to run attacker-controlled script in a user's browser.", reward:"XSS Sense" },
  { id:"attacking-concepts-208", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is command injection conceptually?", options:["Resetting a password","Creating a DNS record","Running a normal software update","Unsafe input causing operating system commands to run"], correct:3, explain:"Command injection occurs when user-controlled input reaches system command execution unsafely.", reward:"Injection Sense" },
  { id:"attacking-concepts-209", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is broken access control?", options:["A flaw where users can access data or actions they should not","A secure login process","A backup failure only","A network cable issue"], correct:0, explain:"Broken access control lets attackers bypass intended permission checks.", reward:"Access Control Abuse" },
  { id:"attacking-concepts-210", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is broken access control dangerous?", options:["It always improves security","It can expose sensitive data or privileged actions to unauthorized users","It prevents all phishing","It disables web browsers"], correct:1, explain:"Access-control flaws can lead directly to data exposure or account abuse.", reward:"Access Control Abuse" },
  { id:"attacking-concepts-211", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is authentication bypass?", options:["Logging in normally with correct credentials","Changing a password after login","Gaining access without completing the intended login process","Backing up an account database"], correct:2, explain:"Authentication bypass lets attackers get access without proving identity properly.", reward:"Auth Abuse" },
  { id:"attacking-concepts-212", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is session theft?", options:["Changing a username","Deleting cookies for privacy","Installing a web patch","Stealing or abusing session data to act as an authenticated user"], correct:3, explain:"Session theft can let attackers bypass repeated login prompts.", reward:"Session Abuse" },
  { id:"attacking-concepts-213", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a malicious attachment?", options:["A file sent to trick a user into opening harmful content","A secure backup file","A normal password reset link","A firewall rule export"], correct:0, explain:"Attachments can deliver malware, scripts, or exploit documents.", reward:"Phishing Basics" },
  { id:"attacking-concepts-214", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a malicious link?", options:["A link to a company's official homepage","A link designed to lead users to harmful or deceptive content","A backup restore URL","A patch management page"], correct:1, explain:"Malicious links may lead to phishing pages, malware, or exploit content.", reward:"Phishing Basics" },
  { id:"attacking-concepts-215", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers impersonate trusted people or brands?", options:["It makes attacks technically impossible","It prevents logs from being created","It increases the chance victims trust the message","It patches email systems"], correct:2, explain:"Trust makes users more likely to click, open, or approve actions.", reward:"Social Engineering" },
  { id:"attacking-concepts-217", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is MFA fatigue?", options:["Repeatedly pushing MFA prompts to pressure a user into approving access","A normal software update","A backup storage limit","A firewall overload"], correct:0, explain:"MFA fatigue attacks try to make users approve a login they did not start.", reward:"MFA Abuse" },
  { id:"attacking-concepts-218", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why can MFA fatigue work?", options:["MFA prompts cannot be abused","Users may approve out of confusion, habit, or pressure","MFA disables all alerts","MFA removes the need for passwords"], correct:1, explain:"Human behavior is part of the attack surface.", reward:"MFA Abuse" },
  { id:"attacking-concepts-219", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a rogue device?", options:["A device with a strong password","A managed company laptop","An unauthorized or unknown device connected to a network","A patched server"], correct:2, explain:"Rogue devices may bypass normal management and monitoring.", reward:"Rogue Device" },
  { id:"attacking-concepts-220", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are rogue devices risky?", options:["They are always fully managed","They cannot communicate","They improve visibility","They may provide unauthorized access or create blind spots"], correct:3, explain:"Unknown devices can create exposure and reduce defender visibility.", reward:"Rogue Device" },
  { id:"attacking-concepts-221", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a malicious USB attack conceptually?", options:["Using removable media to deliver malware or steal data","Charging a phone safely","Installing approved updates","Backing up files securely"], correct:0, explain:"Removable media can be abused for malware delivery or data movement.", reward:"USB Risk" },
  { id:"attacking-concepts-222", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why can removable media be useful to attackers?", options:["It cannot store files","It can bypass some network defenses and interact directly with endpoints","It always requires internet access","It prevents all logging"], correct:1, explain:"USB and removable media can create direct endpoint exposure.", reward:"USB Risk" },
  { id:"attacking-concepts-223", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is physical security's role in cyber attacks?", options:["Physical access never matters","Physical access only affects doors","Physical access can allow device theft, tampering, or direct system access","Physical security replaces MFA"], correct:2, explain:"Cybersecurity and physical access can overlap strongly.", reward:"Physical Security" },
  { id:"attacking-concepts-224", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is an unlocked workstation risky?", options:["It always improves productivity","It prevents malware","It disables attackers","Someone nearby may access data or systems as that user"], correct:3, explain:"Unlocked sessions can be abused by anyone with physical access.", reward:"Physical Security" },
  { id:"attacking-concepts-225", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is account takeover?", options:["An attacker gaining control of someone else's account","A normal account review","A secure password reset","A backup account export"], correct:0, explain:"Account takeover lets attackers act as the victim account.", reward:"Account Takeover" },
  { id:"attacking-concepts-226", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are account takeovers dangerous?", options:["They always disable all alerts","Attackers can abuse trusted access, data, and communication channels","They prevent phishing","They only affect test accounts"], correct:1, explain:"Compromised accounts can be used for fraud, data theft, and lateral access.", reward:"Account Takeover" },
  { id:"attacking-concepts-227", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is an attacker objective?", options:["A random tool name","A firewall rule ID","The goal the attacker is trying to achieve","A backup file path"], correct:2, explain:"Objectives may include access, data theft, disruption, fraud, or persistence.", reward:"Threat Thinking" },
  { id:"attacking-concepts-228", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why should defenders think about attacker objectives?", options:["Objectives replace logs","Objectives prove attribution","Objectives make attacks harmless","They help predict likely targets and next steps"], correct:3, explain:"Understanding goals improves threat hunting and response.", reward:"Threat Thinking" },
  { id:"attacking-concepts-229", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a threat actor?", options:["A person, group, or organization that may conduct malicious activity","A normal backup service","A firewall policy","A secure software patch"], correct:0, explain:"Threat actors can include criminals, insiders, hacktivists, or state groups.", reward:"Threat Actor" },
  { id:"attacking-concepts-230", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is an insider threat?", options:["Only an external hacker","Risk caused by someone with legitimate access, intentionally or accidentally","A DNS resolver","A malware signature"], correct:1, explain:"Insider threats involve people with authorized access who create risk.", reward:"Insider Risk" },
  { id:"attacking-concepts-231", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why can insiders be difficult to detect?", options:["They never use accounts","They cannot access data","Their activity may look like normal authorized work","They do not create logs"], correct:2, explain:"Legitimate access can make misuse harder to distinguish from normal work.", reward:"Insider Risk" },
  { id:"attacking-concepts-232", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a supply-chain attack?", options:["A phishing email only","A local password reset","A firewall mislabel","Compromising a trusted vendor, dependency, update, or service to reach targets"], correct:3, explain:"Supply-chain attacks abuse trusted relationships or software paths.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-233", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are software dependencies part of attack surface?", options:["Third-party code can contain vulnerabilities or malicious changes","Dependencies cannot execute","Dependencies are always reviewed manually","Dependencies remove security risk"], correct:0, explain:"Dependencies become part of the application and can introduce risk.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-234", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is typosquatting?", options:["Changing a password typo","Registering lookalike names to trick users into visiting or installing the wrong thing","Deleting typo logs","Patching a package manager"], correct:1, explain:"Typosquatting abuses mistakes in names, domains, or packages.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-235", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why can fake package names be dangerous?", options:["Package names cannot be abused","Fake packages always fail to install","Users or tools may install malicious packages by mistake","Fake packages prevent all builds"], correct:2, explain:"Package ecosystems can be abused through confusing or lookalike names.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-236", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a malicious update attack?", options:["A normal backup job","A secure patch deployment","A user changing wallpaper","Abusing a trusted update channel to deliver harmful code"], correct:3, explain:"Trusted update paths can distribute malicious changes widely if compromised.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-237", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is data destruction as an attacker impact?", options:["Deleting or damaging data to disrupt operations","Backing up files safely","Installing patches","Creating secure logs"], correct:0, explain:"Data destruction targets availability and recovery.", reward:"Impact Sense" },
  { id:"attacking-concepts-238", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is service disruption?", options:["Improving uptime","Interrupting or degrading normal system availability","Creating a user account","Running a scheduled backup"], correct:1, explain:"Disruption attacks affect availability of services or systems.", reward:"Impact Sense" },
  { id:"attacking-concepts-239", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is denial of service?", options:["Allowing all traffic normally","A secure login flow","Overwhelming or disrupting a service so legitimate users cannot use it","Encrypting backups safely"], correct:2, explain:"DoS attacks target availability.", reward:"DoS Sense" },
  { id:"attacking-concepts-240", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is distributed denial of service?", options:["A single password reset","A normal browser cache issue","A backup duplication process","A denial-of-service attack from many sources"], correct:3, explain:"DDoS uses multiple systems to generate disruptive traffic or requests.", reward:"DoS Sense" },
  { id:"attacking-concepts-241", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is an exploit kit conceptually?", options:["A toolkit or infrastructure used to deliver exploits against vulnerable systems","A secure backup toolkit","A password manager","A firewall configuration file"], correct:0, explain:"Exploit kits automate or package exploitation attempts.", reward:"Exploit Basics" },
  { id:"attacking-concepts-242", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a zero-day vulnerability?", options:["A vulnerability patched years ago","A vulnerability unknown to the vendor or without an available patch","A normal user login","A weekly backup schedule"], correct:1, explain:"Zero-days are dangerous because defenders may not yet have a fix.", reward:"Zero-Day Sense" },
  { id:"attacking-concepts-243", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are zero-days valuable to attackers?", options:["They are always harmless","They cannot be exploited","They may work before defenders have patches or detections","They disable attacker infrastructure"], correct:2, explain:"Unknown vulnerabilities can give attackers a temporary advantage.", reward:"Zero-Day Sense" },
  { id:"attacking-concepts-244", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a proof of concept exploit?", options:["A secure backup plan","A policy document","A normal login session","Demonstration code or steps showing a vulnerability can be exploited"], correct:3, explain:"PoC exploits can help defenders validate risk but may also help attackers.", reward:"Exploit Basics" },
  { id:"attacking-concepts-245", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is responsible disclosure?", options:["Reporting a vulnerability through a coordinated process so it can be fixed","Posting stolen data publicly","Deleting vendor logs","Exploiting systems without permission"], correct:0, explain:"Responsible disclosure aims to reduce harm while helping fix vulnerabilities.", reward:"Disclosure Sense" },
  { id:"attacking-concepts-246", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is authorization important in security testing?", options:["Authorization is only for defenders","Testing without permission can be illegal and harmful","Authorization disables findings","Testing never affects systems"], correct:1, explain:"Security testing must stay within approved scope and permission.", reward:"Ethics Sense" },
  { id:"attacking-concepts-247", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is scope in authorized testing?", options:["The color of a report","The attacker's favorite tool","The systems, actions, and limits allowed for testing","A backup folder"], correct:2, explain:"Scope defines what is allowed and what is off-limits.", reward:"Ethics Sense" },
  { id:"attacking-concepts-248", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why should testers avoid out-of-scope systems?", options:["Out-of-scope systems are always safe","Scope prevents all vulnerabilities","Out-of-scope systems cannot be scanned","Testing them may be unauthorized and cause harm"], correct:3, explain:"Scope protects people, systems, and legal boundaries.", reward:"Ethics Sense" },
  { id:"attacking-concepts-249", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a payload delivery method?", options:["A way attackers deliver malicious content or code to a target","A secure backup storage method","A normal patch schedule","A password policy"], correct:0, explain:"Delivery methods include phishing, downloads, exploits, removable media, or compromised services.", reward:"Payload Sense" },
  { id:"attacking-concepts-250", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is execution in attack terminology?", options:["Deleting old reports","Running attacker-controlled code or commands","Approving a normal change request","Creating a backup"], correct:1, explain:"Execution is when malicious instructions or code actually run.", reward:"Execution Sense" },
  { id:"attacking-concepts-251", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is process lineage useful for defenders studying attacks?", options:["It shows how one process launched another and may reveal the attack chain","It replaces all logs","It proves every child process is malicious","It disables malware"], correct:0, explain:"Process trees show execution relationships and suspicious chains.", reward:"Process Tree" },
  { id:"attacking-concepts-252", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What might Office spawning PowerShell suggest?", options:["Only a normal font update","Possible macro, phishing document, or script-based execution","A guaranteed false positive","A DNS configuration change"], correct:1, explain:"Office launching scripting tools is a classic suspicious pattern.", reward:"Execution Sense" },
  { id:"attacking-concepts-253", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What might a script downloading a file and executing it suggest?", options:["A normal keyboard shortcut","A secure backup job","A staged payload delivery chain","A successful MFA enrollment"], correct:2, explain:"Download-and-execute behavior can indicate multi-stage malware delivery.", reward:"Malware Chain" },
  { id:"attacking-concepts-254", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are user-writable directories abused?", options:["They cannot store files","They are always monitored better than system paths","They are impossible to execute from","Attackers may write and run files there without admin rights"], correct:3, explain:"User-writable paths can support staging and execution.", reward:"Execution Sense" },
  { id:"attacking-concepts-255", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is persistence often hidden in normal system features?", options:["Built-in features such as services or scheduled tasks can look legitimate","Persistence cannot use system features","Normal features prevent attacker access","Hidden persistence always deletes itself"], correct:0, explain:"Attackers may abuse normal mechanisms to blend in.", reward:"Persistence Basics" },
  { id:"attacking-concepts-256", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is persistence through registry run keys?", options:["Updating Windows safely","Adding entries that launch code when a user logs in","Deleting old registry values","Changing keyboard settings"], correct:1, explain:"Run keys can cause programs to start automatically.", reward:"Persistence Basics" },
  { id:"attacking-concepts-257", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is persistence through services?", options:["Using a service configuration to run attacker-controlled code","Disabling all programs permanently","Backing up service logs","Changing DNS records"], correct:0, explain:"Services can run automatically and sometimes with high privileges.", reward:"Persistence Basics" },
  { id:"attacking-concepts-258", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are startup folders monitored by defenders?", options:["They only contain pictures","They cannot run programs","They are used only by backups","They can be abused to launch code automatically"], correct:3, explain:"Startup locations are common persistence points.", reward:"Persistence Basics" },
  { id:"attacking-concepts-259", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is discovery after initial access?", options:["Learning about the system, network, users, permissions, and security tools","Deleting all logs","Reporting a vulnerability responsibly","Restoring a backup"], correct:0, explain:"Discovery helps attackers understand their environment and plan next steps.", reward:"Discovery Sense" },
  { id:"attacking-concepts-260", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers enumerate users and groups?", options:["To patch accounts","To identify privileges, targets, and possible escalation paths","To improve documentation only","To disable malware"], correct:1, explain:"User and group information helps attackers understand access structure.", reward:"Discovery Sense" },
  { id:"attacking-concepts-261", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers look for security tools on a host?", options:["To help defenders","To install official updates","To know what may detect them and how to evade controls","To reset user passwords"], correct:2, explain:"Security-tool discovery supports evasion planning.", reward:"Defense Evasion" },
  { id:"attacking-concepts-262", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers search for files with names like password or backup?", options:["Such files may contain credentials, secrets, or sensitive data","They only contain harmless notes","They always improve security","They cannot be read"], correct:0, explain:"Poorly stored secrets are a common attack path.", reward:"Secret Hunting" },
  { id:"attacking-concepts-263", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is credential harvesting?", options:["Changing all passwords safely","Collecting credentials from phishing pages, files, memory, logs, or systems","Backing up authentication logs","Disabling sign-in pages"], correct:1, explain:"Harvested credentials can support account takeover and lateral movement.", reward:"Credential Theft" },
  { id:"attacking-concepts-264", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are configuration files attractive to attackers?", options:["They cannot contain sensitive data","They always prevent exploitation","They may contain connection strings, usernames, passwords, or keys","They are only images"], correct:2, explain:"Configuration files often reveal how systems connect and authenticate.", reward:"Secret Hunting" },
  { id:"attacking-concepts-265", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is lateral movement using remote desktop?", options:["Using RDP or similar tools to access another system interactively","Changing DNS records","Encrypting local backups","Only browsing the web"], correct:0, explain:"Remote desktop can be abused to control internal systems.", reward:"Lateral Movement" },
  { id:"attacking-concepts-266", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is lateral movement using file shares?", options:["Opening a public website","Using shared folders or SMB paths to copy tools, access data, or move between systems","Changing browser settings","Restoring deleted files"], correct:1, explain:"File shares can help attackers stage tools or access sensitive files.", reward:"Lateral Movement" },
  { id:"attacking-concepts-267", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers use remote execution tools?", options:["Remote execution lets code or commands run on other systems","Remote execution always fails","Remote execution prevents compromise","Remote execution only works offline"], correct:0, explain:"Remote execution supports lateral movement and broader control.", reward:"Lateral Movement" },
  { id:"attacking-concepts-268", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is the risk of shared local administrator passwords?", options:["They improve accountability","Compromise of one password may give access to many machines","They prevent lateral movement","They disable credential theft"], correct:1, explain:"Password reuse across machines expands attacker reach.", reward:"Credential Theft" },
  { id:"attacking-concepts-269", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers target domain controllers?", options:["Domain controllers have no value","They only store browser bookmarks","They are central to identity and may provide broad control","They cannot be logged"], correct:2, explain:"Identity infrastructure is a high-value target.", reward:"Identity Attack" },
  { id:"attacking-concepts-270", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is access to backup systems valuable to attackers?", options:["Backups cannot affect recovery","Backups are always public","Backup access disables malware","Attackers may delete, encrypt, or steal backups to increase impact"], correct:3, explain:"Backups are a major target during ransomware and extortion attacks.", reward:"Impact Sense" },
  { id:"attacking-concepts-271", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is data collection before exfiltration?", options:["Gathering files or information the attacker wants to steal","Patching files","Deleting all sensitive data","Creating a clean backup"], correct:0, explain:"Collection comes before staging or exfiltration in many attack chains.", reward:"Collection Sense" },
  { id:"attacking-concepts-272", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is data staging?", options:["A secure deletion process","Preparing collected data in one place before transfer","A firewall rule test","A password reset flow"], correct:1, explain:"Staging makes exfiltration easier to perform.", reward:"Exfil Basics" },
  { id:"attacking-concepts-273", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why might attackers split exfiltration into smaller transfers?", options:["Small transfers can be harder to notice than one large transfer","Small transfers prevent all detection","Data cannot be sent in large files","Small transfers only happen in backups"], correct:0, explain:"Low-and-slow exfiltration can reduce obvious volume spikes.", reward:"Exfil Basics" },
  { id:"attacking-concepts-274", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers sometimes use encryption or archives before exfiltration?", options:["To make files impossible to move","To help defenders inspect contents","To package data and make contents harder to inspect","To patch stolen files"], correct:2, explain:"Archives and encryption can simplify transfer and hide content.", reward:"Exfil Basics" },
  { id:"attacking-concepts-275", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is indicator-based detection?", options:["Detecting activity using known IPs, domains, hashes, or filenames","Detecting only user emotions","Blocking all network traffic","Disabling logs"], correct:0, explain:"Indicators are useful clues but can change quickly.", reward:"Detection Evasion" },
  { id:"attacking-concepts-276", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers change file hashes?", options:["To avoid hash-based detections","To improve patching","To make files smaller always","To disable execution"], correct:1, explain:"Small changes to a file can produce a new hash.", reward:"Detection Evasion" },
  { id:"attacking-concepts-277", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers rotate domains or IPs?", options:["To make infrastructure easier to block","To prevent malware from communicating","To evade reputation and blocklists","To improve defender visibility"], correct:2, explain:"Changing infrastructure can bypass static indicators.", reward:"Detection Evasion" },
  { id:"attacking-concepts-278", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are behavior-based detections valuable?", options:["They only work on known hashes","They replace all investigation","They disable all false positives","They can catch similar activity even when indicators change"], correct:3, explain:"Behavior is harder to change completely than filenames or hashes.", reward:"Behavior Thinking" },
  { id:"attacking-concepts-279", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is sandbox evasion?", options:["Behavior designed to detect or avoid analysis environments","Running official backups","Installing updates","Changing user roles"], correct:0, explain:"Malware may behave differently if it detects a sandbox.", reward:"Evasion Basics" },
  { id:"attacking-concepts-280", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why might malware delay execution?", options:["To improve user experience","To avoid automated analysis windows or simple detection timing","To patch the host","To reduce persistence"], correct:1, explain:"Delays can help malware evade short sandbox runs.", reward:"Evasion Basics" },
  { id:"attacking-concepts-281", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is fileless malware conceptually?", options:["Malware that only exists on paper","Malware with no network traffic","Malicious activity that relies heavily on memory, scripts, or legitimate tools instead of obvious files","A secure backup method"], correct:2, explain:"Fileless techniques reduce reliance on traditional file artifacts.", reward:"Fileless Sense" },
  { id:"attacking-concepts-282", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is fileless activity harder to detect?", options:["It never creates any evidence","It always disables the computer","It cannot run commands","It may leave fewer obvious file-based indicators"], correct:3, explain:"Defenders often need script, process, memory, and behavior evidence.", reward:"Fileless Sense" },
  { id:"attacking-concepts-283", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is an attacker tradecraft pattern?", options:["A repeated way attackers use tools, techniques, and procedures","A firewall color code","A password policy","A secure backup method"], correct:0, explain:"Tradecraft describes how attackers operate, not only which tools they use.", reward:"Threat Thinking" },
  { id:"attacking-concepts-284", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What does TTP stand for in threat analysis?", options:["Trusted Tool Package","Tactics, Techniques, and Procedures","Temporary Traffic Policy","Token Transfer Protocol"], correct:1, explain:"TTPs describe attacker goals, methods, and patterns.", reward:"Threat Thinking" },
  { id:"attacking-concepts-285", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are TTPs useful to defenders?", options:["They replace evidence","They always identify the attacker by name","They help defenders detect and understand repeated attacker behavior","They disable malware automatically"], correct:2, explain:"TTPs support detection, hunting, and response planning.", reward:"Threat Thinking" },
  { id:"attacking-concepts-286", tier:"Advanced", topic:"Attacking Concepts", prompt:"An attacker uses phishing, token theft, cloud app consent, and mailbox rules. What does this show?", options:["A linked identity-focused attack chain with persistence and data access risk","A simple DNS issue","A normal backup workflow","A harmless browser update"], correct:0, explain:"Multiple identity and mail techniques can combine into a serious compromise.", reward:"Identity Attack" },
  { id:"attacking-concepts-287", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why can cloud app consent create persistence?", options:["Apps cannot access cloud data","Granted app permissions may remain active even after the initial login event","Cloud apps cannot be logged","Consent always expires instantly"], correct:1, explain:"OAuth or app grants can preserve access through tokens and permissions.", reward:"Cloud Attack" },
  { id:"attacking-concepts-288", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do attackers target CI/CD pipelines?", options:["Pipelines cannot deploy software","Pipelines only store images","Pipeline access may allow code, secret, or deployment compromise at scale","Pipelines prevent supply-chain attacks"], correct:2, explain:"CI/CD systems are powerful paths from code to production.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-289", tier:"Advanced", topic:"Attacking Concepts", prompt:"A compromised dependency is included in many applications. What risk does this represent?", options:["Only a local user error","Only a password typo","Only a DNS cache issue","A supply-chain compromise that can spread through trusted software"], correct:3, explain:"Compromised dependencies can affect many downstream systems.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-290", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why are secrets in build logs dangerous?", options:["Logs may expose credentials to people or systems that should not have them","Build logs cannot be copied","Secrets in logs expire instantly","Logs prevent credential misuse"], correct:0, explain:"Secrets exposed in logs may need rotation and investigation.", reward:"Secret Hunting" },
  { id:"attacking-concepts-291", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the attacker value of a misconfigured cloud storage bucket?", options:["It may expose data publicly or to unauthorized users","It always prevents access","It only affects local files","It disables cloud logging"], correct:1, explain:"Cloud storage misconfiguration is a common path to data exposure.", reward:"Cloud Attack" },
  { id:"attacking-concepts-292", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is lateral movement into identity infrastructure especially serious?", options:["Identity systems cannot be abused","Identity systems are low value","It may allow broad control over accounts, access, and authentication","It prevents persistence"], correct:2, explain:"Identity infrastructure compromise can impact the whole environment.", reward:"Identity Attack" },
  { id:"attacking-concepts-293", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the risk of an attacker gaining backup admin access?", options:["Backups cannot be changed","Backup admin access improves recovery","It always triggers automatic restore","They may delete backups, steal data, or prevent recovery"], correct:3, explain:"Backup systems are high-value during destructive or ransomware incidents.", reward:"Impact Sense" },
  { id:"attacking-concepts-294", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do attackers sometimes avoid malware and use credentials instead?", options:["Valid credentials can look like legitimate user activity and bypass some malware defenses","Credentials cannot be monitored","Credentials prevent all logging","Malware is required for every attack"], correct:0, explain:"Credential-based attacks can blend into normal authentication flows.", reward:"Identity Attack" },
  { id:"attacking-concepts-295", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is initial access only the beginning of many attacks?", options:["Initial access always gives full control","Attackers often need to discover, escalate, move laterally, and reach objectives","Initial access prevents exfiltration","Initial access replaces persistence"], correct:1, explain:"Most meaningful attacks progress through multiple stages.", reward:"Attack Chain" },
  { id:"attacking-concepts-296", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why should defenders look for attack progression, not just single alerts?", options:["Single alerts always reveal full scope","Attackers cannot perform multiple steps","Progression shows scope, intent, and next likely actions","Progression makes evidence irrelevant"], correct:2, explain:"Attack progression helps defenders understand and contain incidents.", reward:"Attack Chain" },
  { id:"attacking-concepts-297", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is a high-value target from an attacker perspective?", options:["A random empty test file","A disabled account","A system, account, or data store that helps reach major objectives","A monitor cable"], correct:2, explain:"High-value targets may include domain controllers, cloud admins, backups, and sensitive data stores.", reward:"Threat Thinking" },
  { id:"attacking-concepts-298", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why does attacker dwell time matter?", options:["Longer dwell time may allow more discovery, persistence, theft, or movement","Dwell time prevents compromise","Dwell time only measures internet speed","Dwell time deletes logs"], correct:0, explain:"The longer attackers remain undetected, the more they may accomplish.", reward:"Threat Thinking" },
  { id:"attacking-concepts-299", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why should defenders care about attacker cost?", options:["Attacker cost is unrelated to defense","Raising attacker cost can discourage, delay, or expose malicious activity","Lower attacker cost improves security","Attackers never change behavior"], correct:1, explain:"Good controls make attacks harder, noisier, slower, or less profitable.", reward:"Defense Thinking" },
  { id:"attacking-concepts-300", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the key defensive lesson from studying attack chains?", options:["One control is enough","Only malware matters","Defenders can break the chain at many points with layered controls and visibility","Logs are unnecessary"], correct:2, explain:"Layered defense can stop, slow, or reveal attackers at different stages.", reward:"Defense Thinking" },
  { id:"attacking-concepts-301", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is the main idea of an attack lifecycle?", options:["An attack often happens in stages rather than one single action","All attacks start with ransomware","Attackers always use the same tool","Defenders should ignore early activity"], correct:0, explain:"Attack lifecycles help defenders understand progression from early access to final objectives.", reward:"Attack Chain" },
  { id:"attacking-concepts-302", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why is early detection valuable?", options:["Early alerts are always false positives","Stopping activity early can prevent escalation, movement, or impact","Early detection removes the need for logs","Attackers cannot change tactics"], correct:1, explain:"Finding activity early can limit damage before attackers reach bigger goals.", reward:"Early Detection" },
  { id:"attacking-concepts-303", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a foothold in attacker terminology?", options:["A backup system","A firewall policy","Initial access that lets an attacker begin operating in an environment","A secure configuration baseline"], correct:2, explain:"A foothold is an initial position attackers can use to continue activity.", reward:"Initial Access" },
  { id:"attacking-concepts-304", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers try to expand from a foothold?", options:["Footholds always give full control","Expansion prevents all logging","Attackers cannot act from one system","They may need more access to reach valuable systems or data"], correct:3, explain:"Initial access is often limited, so attackers try to expand access.", reward:"Attack Chain" },
  { id:"attacking-concepts-305", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a phishing landing page?", options:["A fake or deceptive page used to trick users into entering information","A secure backup portal","A normal DNS resolver","A firewall dashboard"], correct:0, explain:"Phishing landing pages often mimic legitimate login or service pages.", reward:"Phishing Basics" },
  { id:"attacking-concepts-306", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a fake login page used for?", options:["Installing patches","Stealing credentials or session information","Creating backups","Improving MFA strength"], correct:1, explain:"Fake login pages trick users into entering credentials or approving access.", reward:"Credential Theft" },
  { id:"attacking-concepts-307", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers use urgent language in phishing?", options:["Urgency patches systems","Urgency disables links","Urgency pressures users into acting before thinking carefully","Urgency prevents credential theft"], correct:2, explain:"Urgency is a social engineering technique used to reduce careful review.", reward:"Social Engineering" },
  { id:"attacking-concepts-308", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is impersonation in attacks?", options:["Installing official software","Backing up user files","Updating DNS records","Pretending to be a trusted person, company, or service"], correct:3, explain:"Impersonation abuses trust to influence a victim's actions.", reward:"Social Engineering" },
  { id:"attacking-concepts-309", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is malicious redirection?", options:["Sending a user through links or redirects toward harmful content","Changing a password safely","Restoring a server","Applying a patch"], correct:0, explain:"Redirect chains can hide the final phishing or malware destination.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-310", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers use URL shorteners?", options:["They always improve security","They can hide the final destination from the user","They prevent tracking","They block malware scans"], correct:1, explain:"Short links can make destination review harder.", reward:"Phishing Basics" },
  { id:"attacking-concepts-311", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is attachment-based phishing?", options:["Only sending newsletters","Blocking all email","Using an attached file to trick users into opening malicious or deceptive content","Updating a mailbox"], correct:2, explain:"Attachments can contain malware, links, scripts, or exploit content.", reward:"Phishing Basics" },
  { id:"attacking-concepts-312", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers use trusted file types like documents or PDFs?", options:["Documents cannot contain risk","PDFs always block malware","Trusted file types cannot be scanned","Users are more likely to open familiar business documents"], correct:3, explain:"Familiar file types can make malicious content seem normal.", reward:"Social Engineering" },
  { id:"attacking-concepts-313", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is malicious macro abuse?", options:["Using document macros to run unwanted commands or code","Creating a safe spreadsheet formula","Backing up an email","Changing a monitor setting"], correct:0, explain:"Macros can automate useful tasks, but attackers may abuse them for execution.", reward:"Execution Sense" },
  { id:"attacking-concepts-314", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are script files risky when received unexpectedly?", options:["Script files cannot execute","They may run commands on the system if opened or launched","They always improve security","They only contain images"], correct:1, explain:"Scripts can automate harmful actions if users run them.", reward:"Script Abuse" },
  { id:"attacking-concepts-315", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a malicious shortcut file risk?", options:["Shortcuts cannot launch programs","Shortcuts only open folders","A shortcut can be crafted to run commands or launch suspicious files","Shortcuts are always safe"], correct:2, explain:"Shortcut files can point to commands, scripts, or payloads.", reward:"Execution Sense" },
  { id:"attacking-concepts-316", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is drive-by download conceptually?", options:["Downloading files from a USB drive","Installing updates from a vendor","Backing up a browser profile","A website causing a download or exploit with little user interaction"], correct:3, explain:"Drive-by activity abuses web browsing or browser/plugin weaknesses.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-317", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is exploitation of weak passwords?", options:["Guessing or abusing passwords that are easy, reused, leaked, or default","Encrypting password vaults","Patching authentication servers","Writing user training"], correct:0, explain:"Weak passwords make account compromise easier.", reward:"Password Attacks" },
  { id:"attacking-concepts-318", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are default credentials dangerous?", options:["They prevent brute force","Attackers often know and try common default usernames and passwords","They improve audit logs","They disable remote access"], correct:1, explain:"Default credentials are widely known and should be changed.", reward:"Password Attacks" },
  { id:"attacking-concepts-319", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is an exposed admin panel?", options:["A local text file","A secure backup copy","An administrative interface reachable by people who should not access it","A disabled user account"], correct:2, explain:"Exposed admin panels can provide high-impact access if abused.", reward:"Attack Surface" },
  { id:"attacking-concepts-320", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are public admin interfaces risky?", options:["Admin interfaces cannot change systems","They prevent all exploitation","They always require no password","They provide powerful targets for guessing, exploitation, or abuse"], correct:3, explain:"Admin interfaces should be strongly protected and limited.", reward:"Attack Surface" },
  { id:"attacking-concepts-321", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is vulnerability chaining?", options:["Combining multiple weaknesses to achieve a larger result","Deleting vulnerability reports","Installing all patches","Writing a secure baseline"], correct:0, explain:"Several smaller weaknesses can combine into serious compromise.", reward:"Attack Path" },
  { id:"attacking-concepts-322", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers search for exposed files?", options:["Exposed files cannot contain useful data","Files may reveal credentials, configuration, backups, or sensitive information","Files always block attackers","Exposed files prevent reconnaissance"], correct:1, explain:"Public or misconfigured files can leak valuable information.", reward:"Secret Hunting" },
  { id:"attacking-concepts-323", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is directory listing risk?", options:["A user listing their own downloads","A firewall listing rules internally","A web server showing files and folders that should not be exposed","A backup index stored offline"], correct:2, explain:"Directory listing can reveal sensitive files or application structure.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-324", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are backup files on web servers risky?", options:["Backups are always encrypted","Backup files cannot be downloaded","Backups improve security by being public","They may expose source code, credentials, or sensitive data"], correct:3, explain:"Backups should not be left publicly reachable.", reward:"Exposure Sense" },
  { id:"attacking-concepts-325", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is information disclosure?", options:["Unintended exposure of information that helps attackers or reveals sensitive data","Securely encrypting data","Deleting secrets","Testing backups"], correct:0, explain:"Information disclosure can reveal paths, versions, users, keys, or internal details.", reward:"Exposure Sense" },
  { id:"attacking-concepts-326", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are error messages sometimes useful to attackers?", options:["Error messages always prevent attacks","They may reveal paths, software, database errors, or internal details","They disable exploitation","They remove all sensitive data"], correct:1, explain:"Verbose errors can leak information useful for attack planning.", reward:"Exposure Sense" },
  { id:"attacking-concepts-327", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a leaked API key?", options:["A normal public username","A secure password reset","A secret key exposed where unauthorized people can see or use it","A firewall log setting"], correct:2, explain:"Leaked API keys may allow access to services or data.", reward:"Secret Hunting" },
  { id:"attacking-concepts-328", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are leaked API keys dangerous?", options:["API keys cannot be used","API keys always expire instantly","API keys are only labels","They may allow unauthorized automated access to resources"], correct:3, explain:"Exposed keys should be revoked or rotated quickly.", reward:"Secret Hunting" },
  { id:"attacking-concepts-329", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is attacker infrastructure?", options:["Systems, domains, servers, or services used to support attacker operations","A secure company laptop","A backup vault","A normal helpdesk process"], correct:0, explain:"Infrastructure may host payloads, phishing pages, C2, or exfiltration endpoints.", reward:"Infrastructure Sense" },
  { id:"attacking-concepts-330", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers rotate infrastructure?", options:["To make blocking and reputation tracking harder","To improve defender visibility","To stop their own attack","To patch victim systems"], correct:1, explain:"Changing domains or IPs can evade static blocks.", reward:"Infrastructure Sense" },
  { id:"attacking-concepts-331", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a command server?", options:["A server used for normal backups only","A system that assigns user passwords","Infrastructure used to send instructions or receive check-ins from compromised systems","A DNS root server only"], correct:2, explain:"Command servers support attacker control over compromised systems.", reward:"C2 Basics" },
  { id:"attacking-concepts-332", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers hide C2 in normal-looking traffic?", options:["Normal-looking traffic cannot be detected","It prevents all network logging","It patches the victim system","It may blend with expected business communication"], correct:3, explain:"Blending in makes detection harder.", reward:"C2 Basics" },
  { id:"attacking-concepts-333", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is payload staging?", options:["Preparing or placing additional attacker code or tools for later execution","Running a backup restore","Updating antivirus","Creating a secure password"], correct:0, explain:"Staging helps attackers deliver or run later components.", reward:"Malware Chain" },
  { id:"attacking-concepts-334", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a multi-stage attack?", options:["A single failed login only","An attack that progresses through multiple steps or components","A normal software update","A fully patched system"], correct:1, explain:"Multi-stage attacks may include downloaders, payloads, persistence, and C2.", reward:"Attack Chain" },
  { id:"attacking-concepts-335", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are multi-stage attacks harder to analyze?", options:["They never create logs","They always happen instantly","Evidence may be spread across several files, processes, hosts, or times","They cannot use the network"], correct:2, explain:"Analysts must connect related stages into one timeline.", reward:"Attack Chain" },
  { id:"attacking-concepts-336", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a loader?", options:["A firewall backup","A user training page","A normal keyboard driver","A component that loads or starts another payload"], correct:3, explain:"Loaders help execute additional malicious components.", reward:"Malware Chain" },
  { id:"attacking-concepts-337", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is attacker cleanup?", options:["Removing tools, logs, or traces to reduce evidence","Installing EDR","Writing documentation","Applying patches"], correct:0, explain:"Attackers may clean up to hide activity and slow investigations.", reward:"Evasion Basics" },
  { id:"attacking-concepts-338", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why might attackers delete logs?", options:["To make logs more useful","To hide evidence of their activity","To help defenders investigate","To restore systems"], correct:1, explain:"Log deletion is a common sign of defense evasion.", reward:"Log Tampering" },
  { id:"attacking-concepts-339", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is timestomping conceptually?", options:["Updating system time correctly","Creating backup timestamps","Changing file timestamps to mislead investigators","Synchronizing logs"], correct:2, explain:"Timestamp manipulation can make timelines harder to trust.", reward:"Evasion Basics" },
  { id:"attacking-concepts-340", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers rename tools?", options:["Renaming tools prevents execution","Renaming tools automatically gives admin rights","Renaming tools patches vulnerabilities","To make malicious or suspicious tools look ordinary"], correct:3, explain:"Renaming supports masquerading and evasion.", reward:"Masquerading" },
  { id:"attacking-concepts-341", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a decoy file in social engineering?", options:["A file designed to look legitimate while distracting or deceiving the victim","A secure encrypted backup","A firewall log","A patch installer from a vendor"], correct:0, explain:"Decoys can make malicious activity seem normal.", reward:"Social Engineering" },
  { id:"attacking-concepts-342", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a lure in phishing?", options:["A backup file","The message, offer, or story used to attract the victim's action","A secure DNS record","A vulnerability patch"], correct:1, explain:"The lure is the bait that encourages the target to click or respond.", reward:"Phishing Basics" },
  { id:"attacking-concepts-343", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why do attackers use business-themed lures?", options:["Business themes cannot be malicious","Business themes are always blocked","They can match normal work expectations and seem believable","They prevent email delivery"], correct:2, explain:"A believable business context increases the chance of user interaction.", reward:"Social Engineering" },
  { id:"attacking-concepts-344", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a watering hole attack?", options:["Attacking only water treatment plants","Scanning every port on a network","Changing a user's password","Compromising or abusing a site visited by the target group"], correct:3, explain:"Watering hole attacks target places victims are likely to visit.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-345", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is attacker persistence through browser extensions?", options:["Using an extension to maintain access, collect data, or manipulate browser activity","Installing a secure browser update","Clearing browser cache","Blocking malicious ads"], correct:0, explain:"Malicious extensions can access browsing activity or sessions.", reward:"Persistence Basics" },
  { id:"attacking-concepts-346", tier:"Beginner", topic:"Attacking Concepts", prompt:"Why are malicious browser extensions risky?", options:["Extensions cannot access data","They may read pages, steal information, or alter browser behavior","Extensions always improve security","Extensions cannot persist"], correct:1, explain:"Extensions can have powerful permissions in the browser.", reward:"Browser Abuse" },
  { id:"attacking-concepts-347", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is clipboard hijacking?", options:["Changing a monitor setting","Backing up files","Altering copied data, such as wallet addresses or commands","Resetting a password"], correct:2, explain:"Clipboard hijacking abuses what users copy and paste.", reward:"Malware Basics" },
  { id:"attacking-concepts-348", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is keylogging?", options:["Encrypting all keystrokes safely","Deleting keyboard drivers","Updating a keyboard layout","Recording keystrokes to capture information"], correct:3, explain:"Keylogging can steal passwords, messages, and sensitive input.", reward:"Spyware Sense" },
  { id:"attacking-concepts-349", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is screen capture spyware?", options:["Malware or software that records screenshots or screen activity without authorization","A secure meeting tool","A DNS service","A backup image"], correct:0, explain:"Screen capture can expose sensitive information visible to the user.", reward:"Spyware Sense" },
  { id:"attacking-concepts-350", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is browser credential theft?", options:["Updating saved passwords safely","Stealing credentials or session data stored or used by the browser","Deleting browser bookmarks","Installing browser patches"], correct:1, explain:"Browsers often contain valuable session and credential material.", reward:"Credential Theft" },
  { id:"attacking-concepts-351", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers prefer valid accounts when possible?", options:["Valid accounts can blend into normal authentication and access patterns","Valid accounts cannot access data","Valid accounts prevent persistence","Valid accounts always trigger malware alerts"], correct:0, explain:"Valid account abuse can be harder to distinguish from legitimate behavior.", reward:"Identity Attack" },
  { id:"attacking-concepts-352", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is account discovery?", options:["Deleting unused accounts","Finding users, groups, roles, or permissions in an environment","Backing up identity logs","Creating MFA policies"], correct:1, explain:"Account discovery helps attackers understand identity structure.", reward:"Discovery Sense" },
  { id:"attacking-concepts-353", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers look for privileged groups?", options:["Privileged groups cannot be abused","Privileged groups are only decorative","They reveal accounts or paths with high-impact permissions","They disable all malware"], correct:2, explain:"Privileged groups help attackers identify escalation targets.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-354", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is token replay conceptually?", options:["Changing a password safely","Encrypting a token for storage","Deleting old sessions","Reusing stolen session or access tokens to authenticate"], correct:3, explain:"Token replay can bypass normal login if tokens remain valid.", reward:"Token Theft" },
  { id:"attacking-concepts-355", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers target password vaults?", options:["Vaults may contain many high-value credentials or secrets","Vaults cannot store passwords","Vaults are always public","Vaults prevent credential theft"], correct:0, explain:"Compromising a vault can give broad access.", reward:"Credential Theft" },
  { id:"attacking-concepts-356", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is secret scanning from an attacker's perspective?", options:["Patching exposed keys","Searching files, repos, logs, or configs for credentials and tokens","Creating secure passwords","Deleting all secrets"], correct:1, explain:"Attackers may search for secrets that provide further access.", reward:"Secret Hunting" },
  { id:"attacking-concepts-357", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are old credentials still dangerous?", options:["Old credentials cannot work","Old credentials are always deleted","They may still be valid, reused, or forgotten in scripts and configs","Old credentials prevent attacks"], correct:2, explain:"Stale secrets are common hidden attack paths.", reward:"Secret Hunting" },
  { id:"attacking-concepts-358", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is privilege escalation through misconfigured permissions?", options:["Using overly broad permissions to gain more access or control","Changing screen brightness","Running a normal backup","Installing a vendor patch"], correct:0, explain:"Weak permissions can create unintended access paths.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-359", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers search for writable service paths?", options:["Writable paths are always safe","Writable paths can allow replacement or modification of code run by a service","Writable paths prevent persistence","Services cannot run files"], correct:1, explain:"If an attacker can alter what a service runs, they may gain execution or privilege.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-360", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is DLL hijacking conceptually?", options:["Deleting all DLL files","Using DLL search or loading behavior to make a program load attacker-controlled code","Backing up DLL files","Updating Windows securely"], correct:1, explain:"DLL hijacking abuses how applications find and load libraries.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-361", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers check local privilege escalation opportunities?", options:["Local escalation cannot help attackers","Higher local privileges can allow defense evasion, credential access, or persistence","Local privileges only affect printers","Local escalation prevents lateral movement"], correct:1, explain:"Higher local privilege gives attackers more control over a host.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-362", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is kernel-level privilege escalation?", options:["A user changing their wallpaper","Backing up system files","Abusing a low-level flaw to gain very high system privileges","Running a browser update"], correct:2, explain:"Kernel-level access can provide deep control of a system.", reward:"Privilege Escalation" },
  { id:"attacking-concepts-363", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are exposed management interfaces attractive?", options:["They often provide powerful control if accessed or exploited","They never require login","They cannot be attacked","They only show public text"], correct:0, explain:"Management interfaces should be restricted and monitored.", reward:"Attack Surface" },
  { id:"attacking-concepts-364", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is exploitation of insecure deserialization conceptually?", options:["Changing a file extension","Abusing unsafe object parsing to cause unintended behavior or code execution","Backing up application data","Installing a patch"], correct:1, explain:"Unsafe deserialization can let attackers manipulate how data becomes objects or code paths.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-365", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is server-side request forgery conceptually?", options:["A user resetting a password","A normal browser bookmark","A server being tricked into making requests chosen by an attacker","A secure backup task"], correct:2, explain:"SSRF can let attackers reach internal resources through a server.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-366", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is SSRF dangerous?", options:["It can never reach anything internal","It only changes CSS","It prevents reconnaissance","It may allow access to internal services, metadata, or restricted endpoints"], correct:3, explain:"SSRF can abuse server trust and network position.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-367", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is file upload abuse?", options:["Uploading files that allow code execution, phishing, malware hosting, or data misuse","Uploading approved documents normally","Deleting uploaded files","Running a backup job"], correct:0, explain:"Unsafe upload handling can create serious attack paths.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-368", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why should uploaded files be validated by defenders?", options:["Validation is only cosmetic","Attackers may upload scripts, malware, oversized files, or disguised content","Validation prevents all attacks forever","Uploaded files cannot be dangerous"], correct:1, explain:"File upload features are common abuse points.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-369", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is path traversal conceptually?", options:["Encrypting a filepath","Backing up folders","Using crafted paths to access files outside the intended directory","Changing a folder icon"], correct:2, explain:"Path traversal abuses file path handling to reach unintended files.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-370", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is path traversal dangerous?", options:["It always fails","It only affects images","It prevents attackers from reading files","It may expose sensitive files like configs, keys, or source code"], correct:3, explain:"Improper path handling can reveal restricted files.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-371", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is remote code execution?", options:["An attacker causing code to run on a target system from outside or through an application","A secure code review","A password reset","A backup restore"], correct:0, explain:"RCE is high impact because it can let attackers run commands or payloads.", reward:"RCE Sense" },
  { id:"attacking-concepts-372", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is RCE usually serious?", options:["RCE only affects documentation","It may give attackers direct execution capability on a system","RCE prevents persistence","RCE means the system is patched"], correct:1, explain:"Execution capability can lead to broader compromise.", reward:"RCE Sense" },
  { id:"attacking-concepts-373", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is local file inclusion conceptually?", options:["A backup folder sync","A normal user login","A web app including or reading local files based on unsafe input","A firewall deny rule"], correct:2, explain:"LFI can expose local files or sometimes support code execution chains.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-374", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is remote file inclusion conceptually?", options:["A web app including remote content controlled by an attacker","A normal patch download","A secure DNS query","A local password reset"], correct:0, explain:"RFI can lead to malicious code or content being loaded by an application.", reward:"Web Attack Sense" },
  { id:"attacking-concepts-375", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers abuse weak API authorization?", options:["APIs cannot expose data","APIs are always public by design","Weak authorization can allow access to data or actions outside the user's rights","APIs prevent attack chains"], correct:2, explain:"APIs must enforce access rules server-side.", reward:"API Abuse" },
  { id:"attacking-concepts-376", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is IDOR conceptually?", options:["A backup ID format","A DNS record type","A secure login method","Accessing another user's object by changing an identifier when authorization is weak"], correct:3, explain:"Insecure direct object reference is a common access-control weakness.", reward:"API Abuse" },
  { id:"attacking-concepts-377", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are APIs attractive targets?", options:["They often expose data and functions directly to applications and automation","APIs cannot be attacked","APIs never require authentication","APIs contain no business logic"], correct:0, explain:"APIs are powerful interfaces and must be protected.", reward:"API Abuse" },
  { id:"attacking-concepts-378", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is rate-limit abuse?", options:["Using a system normally once","Sending many requests to guess, scrape, brute force, or overload functionality","Installing a firewall","Changing a password safely"], correct:1, explain:"Weak rate limits can enable automated abuse.", reward:"API Abuse" },
  { id:"attacking-concepts-379", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why is business logic abuse hard to detect?", options:["It often uses valid features in unintended ways","It cannot create logs","It always uses malware","It only affects offline systems"], correct:0, explain:"Business logic abuse may not look like a technical exploit at first.", reward:"Logic Abuse" },
  { id:"attacking-concepts-380", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is an example of business logic abuse?", options:["Installing approved updates","Using a feature sequence to bypass intended limits or gain unfair benefit","Restoring a backup","Changing a theme"], correct:1, explain:"Business logic abuse exploits workflow assumptions rather than classic bugs.", reward:"Logic Abuse" },
  { id:"attacking-concepts-381", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers test application limits?", options:["To find weak rate limits, authorization flaws, or unexpected behavior","To help defenders only","To improve backups","To disable their own access"], correct:0, explain:"Testing limits can reveal abuse opportunities.", reward:"Logic Abuse" },
  { id:"attacking-concepts-382", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is enumeration through an application?", options:["Deleting old sessions","Discovering valid users, resources, IDs, or data through application behavior","Installing antivirus","Backing up files"], correct:1, explain:"Application responses can reveal what exists.", reward:"Enumeration Sense" },
  { id:"attacking-concepts-383", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why are verbose API errors risky?", options:["They always fix bugs","They prevent exploitation","They may reveal internal logic, fields, paths, or stack traces","They disable access"], correct:2, explain:"Detailed errors can help attackers refine requests.", reward:"Exposure Sense" },
  { id:"attacking-concepts-384", tier:"Intermediate", topic:"Attacking Concepts", prompt:"What is abuse of overly broad permissions?", options:["Using excessive access granted to an account, token, app, or service","Reducing access to least privilege","Deleting unused roles","Patching an account"], correct:0, explain:"Overly broad permissions create larger attack paths.", reward:"Misconfig Abuse" },
  { id:"attacking-concepts-385", tier:"Intermediate", topic:"Attacking Concepts", prompt:"Why do attackers seek cloud metadata services?", options:["They are always empty","They may expose temporary credentials or instance information if reachable","They prevent all cloud access","They only store images"], correct:1, explain:"Cloud metadata endpoints can be valuable if misused through SSRF or host access.", reward:"Cloud Attack" },
  { id:"attacking-concepts-386", tier:"Advanced", topic:"Attacking Concepts", prompt:"An attacker exploits SSRF to access cloud metadata and obtain temporary credentials. What attack chain is shown?", options:["Web flaw leading to cloud credential access and possible cloud compromise","Only a DNS misconfiguration","A normal backup process","A harmless browser redirect"], correct:0, explain:"This chain connects web exploitation with cloud identity abuse.", reward:"Attack Chain" },
  { id:"attacking-concepts-387", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is behavior-based detection useful against attacker tool changes?", options:["Behavior cannot be logged","Attackers can change filenames and tools, but similar behaviors may remain visible","Behavior detection prevents all false positives","Tool names are always stable"], correct:1, explain:"Behavior-focused detection is more resilient than static names alone.", reward:"Behavior Thinking" },
  { id:"attacking-concepts-388", tier:"Advanced", topic:"Attacking Concepts", prompt:"A user account logs in, grants OAuth consent, exports mail, then creates forwarding rules. What is this likely pattern?", options:["A normal DNS update","A harmless screen change","Account compromise with persistence and collection or exfiltration behavior","A local software patch"], correct:2, explain:"The sequence shows identity access, persistence, and possible data theft.", reward:"Identity Attack" },
  { id:"attacking-concepts-389", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why should defenders focus on attack paths to critical assets?", options:["Critical assets cannot be compromised","Attack paths are only useful for reports","Attack paths replace all controls","Breaking paths reduces the chance small weaknesses become major incidents"], correct:3, explain:"Attack path analysis helps prioritize defensive improvements.", reward:"Attack Path" },
  { id:"attacking-concepts-390", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the danger of a flat internal network from an attacker perspective?", options:["A foothold may allow easier movement to many systems","It prevents lateral movement","It makes attackers easier to stop automatically","It disables credential theft"], correct:0, explain:"Flat networks can increase blast radius after compromise.", reward:"Lateral Movement" },
  { id:"attacking-concepts-391", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do attackers value backup destruction before ransomware deployment?", options:["Backups have no relation to recovery","Destroying backups increases pressure by reducing recovery options","Backups cannot be modified","Backup destruction prevents encryption"], correct:1, explain:"Ransomware operators may target backups to increase impact.", reward:"Impact Sense" },
  { id:"attacking-concepts-392", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is data theft sometimes combined with ransomware?", options:["Data theft prevents encryption","Ransomware cannot disrupt systems","Stolen data can be used for extortion even if backups restore systems","Data theft makes incidents harmless"], correct:2, explain:"Double-extortion attacks combine availability and confidentiality pressure.", reward:"Impact Sense" },
  { id:"attacking-concepts-393", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why should defenders monitor for both encryption activity and data staging?", options:["Encryption and staging are unrelated","Data staging cannot happen before ransomware","Only encryption matters","Attackers may steal data before encrypting systems"], correct:3, explain:"Ransomware incidents may include collection and exfiltration before impact.", reward:"Exfil Basics" },
  { id:"attacking-concepts-394", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why can legitimate remote monitoring tools be abused?", options:["They provide remote access capabilities that attackers may use if installed or stolen","They cannot connect to systems","They prevent attacker access","They never create logs"], correct:0, explain:"Legitimate admin tools can become attacker tools when abused.", reward:"LOLBins Sense" },
  { id:"attacking-concepts-395", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is a risk of over-relying on malware signatures?", options:["Signatures always catch all threats","Attackers may modify malware or use non-malware techniques to avoid signature matches","Signatures replace behavior analysis","Signatures cannot be bypassed"], correct:1, explain:"Signature detection is useful but limited.", reward:"Detection Evasion" },
  { id:"attacking-concepts-396", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why do attackers abuse trusted relationships?", options:["Trusted relationships can provide easier access through vendors, partners, apps, or integrations","Trusted relationships cannot be attacked","Trust always reduces attacker access","Vendors never hold credentials"], correct:0, explain:"Trust paths can become attack paths.", reward:"Supply Chain Attack" },
  { id:"attacking-concepts-397", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why is an attacker's operational security relevant to defenders?", options:["It has no defensive value","It describes how attackers avoid exposure and can reveal patterns defenders hunt for","It prevents all logs","It means defenders should stop monitoring"], correct:1, explain:"Attacker OPSEC mistakes and habits can create detection opportunities.", reward:"Threat Thinking" },
  { id:"attacking-concepts-398", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the defensive lesson from attacker infrastructure reuse?", options:["Infrastructure reuse can link campaigns or activity clusters for hunting","Reuse makes attacks impossible to detect","Reuse proves all activity is benign","Infrastructure never appears in logs"], correct:0, explain:"Repeated domains, certificates, IPs, or patterns can support attribution and detection.", reward:"Infrastructure Sense" },
  { id:"attacking-concepts-399", tier:"Advanced", topic:"Attacking Concepts", prompt:"Why should defenders study failed attacker actions?", options:["Failed actions can reveal intent, tooling, targets, and blocked attack paths","Failed actions are never logged","Only successful actions matter","Failed actions prove no risk exists"], correct:0, explain:"Blocked or failed attempts can still provide valuable intelligence.", reward:"Defense Thinking" },
  { id:"attacking-concepts-400", tier:"Advanced", topic:"Attacking Concepts", prompt:"What is the strongest defensive mindset when learning attacking concepts?", options:["Memorize tool names only","Ignore attacker goals","Understand behaviors, chains, objectives, and how controls can break them","Assume every attack is identical"], correct:2, explain:"Defenders become stronger by understanding attacker behavior and how to interrupt it.", reward:"Defense Thinking" },
  { id:"attacking-concepts-401", tier:"Beginner", topic:"Attacking Concepts", prompt:"How does typosquatting trick users?", options:["Splitting one website across several backend servers","Encrypting a domain name before it is published","Renaming a company's internal file shares","Registering misspelled domains to catch users who mistype"], correct:3, explain:"Typosquatting registers look-alike misspelled domains so people who mistype a real address reach the attacker.", reward:"Domain Caution" },
  { id:"attacking-concepts-402", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is vishing?", options:["Backing up recorded voicemail messages safely","A way to speed up the quality of voice calls","A type of encrypted video conferencing tool","Phishing that is carried out over a voice phone call"], correct:3, explain:"Vishing is voice phishing: attackers call and use pressure or pretexting to extract information or actions.", reward:"Phishing Sense" },
  { id:"attacking-concepts-403", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a watering-hole attack?", options:["Backing up a website to a second standby server","Adding extra bandwidth to a very busy website","Compromising a site the target group often visits","Blocking a website from loading any of its images"], correct:2, explain:"A watering-hole attack infects a site the intended victims commonly use, so regular visitors get compromised.", reward:"Recon Awareness" },
  { id:"attacking-concepts-404", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is scareware?", options:["Software that schedules routine overnight backups","A tool that measures how fast a disk runs","A setting that dims the screen to save power","Fake alerts that frighten users into paying or installing"], correct:3, explain:"Scareware shows alarming fake warnings to pressure users into buying useless software or running malware.", reward:"Human Firewall" },
  { id:"attacking-concepts-405", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a drive-by download?", options:["Downloading only after a manual approval step","A scheduled download that runs every single night","Malware that downloads just from visiting a bad page","A browser feature that saves pages for offline use"], correct:2, explain:"A drive-by download installs malware automatically when a user merely visits a compromised or malicious page.", reward:"Web Defense" },
  { id:"attacking-concepts-406", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is the goal of credential harvesting?", options:["Backing up passwords into an encrypted vault","Resetting expired passwords across the company","Counting how many accounts each user owns","Collecting many logins, often via fake login pages"], correct:3, explain:"Credential harvesting gathers usernames and passwords in bulk, frequently using fake sign-in pages.", reward:"Credential Guard" },
  { id:"attacking-concepts-407", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a supply-chain attack in simple terms?", options:["Attacking a company's loading dock and delivery trucks","Flooding a store checkout with many fake orders","Compromising a trusted vendor or update to reach customers","Sending so much traffic that a website crashes"], correct:2, explain:"A supply-chain attack hits a trusted supplier, tool, or update so malicious code spreads to its many customers.", reward:"Chain Awareness" },
  { id:"attacking-concepts-408", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is clickjacking?", options:["Clicking links faster than a normal user can","Logging every mouse click for website analytics","Blocking all clicks until a page fully loads","Tricking a user into clicking something hidden"], correct:3, explain:"Clickjacking overlays hidden elements so a user's click does something different from what they intended.", reward:"Web Defense" },
  { id:"attacking-concepts-409", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is a logic bomb?", options:["Software that tests a program's logic for bugs","A backup that triggers only when a disk is full","Malicious code that triggers when a condition is met","A firewall rule that blocks risky logic errors"], correct:2, explain:"A logic bomb is hidden code that activates its harmful action when a specific condition or time is reached.", reward:"Impact Sense" },
  { id:"attacking-concepts-410", tier:"Beginner", topic:"Attacking Concepts", prompt:"What is malvertising?", options:["Advertising a security product to many users","Measuring how many people click an online ad","Blocking ads from loading on a web page","Malicious online ads that deliver malware or scams"], correct:3, explain:"Malvertising hides malware or scam redirects inside online advertisements, sometimes on legitimate sites.", reward:"Web Defense" },
];

if (typeof module !== "undefined" && module.exports) module.exports = ATTACKING_CONCEPTS_QUESTIONS;
